DROP TABLE IF EXISTS `access_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `access_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `access_time` int unsigned NOT NULL DEFAULT '0' COMMENT '访问时间',
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'ip地址',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品id',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  `params_id` int unsigned NOT NULL DEFAULT '0' COMMENT '参数id',
  `controller` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '控制器',
  `access_domain` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '访问域名',
  `access_path` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '访问地址',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `access_time` (`access_time`) USING BTREE,
  KEY `shop_id` (`shop_id`) USING BTREE,
  KEY `goods_id` (`product_id`) USING BTREE,
  KEY `ip_address` (`ip_address`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='访问日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

