/*!40000 ALTER TABLE `access_log` ENABLE KEYS */;
DROP TABLE IF EXISTS `admin_api_token`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_api_token` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` int NOT NULL COMMENT '关联管理员ID',
  `token_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Token的SHA-256哈希',
  `token_prefix` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Token前8位，用于展示标识',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'Token名称/备注',
  `created_at` bigint NOT NULL COMMENT '创建时间戳',
  `last_used_at` bigint DEFAULT NULL COMMENT '最后使用时间戳',
  `expires_at` bigint DEFAULT NULL COMMENT '过期时间戳，NULL表示永不过期',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '是否有效：1 有效 0 已吊销',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_token_hash` (`token_hash`),
  KEY `idx_admin_id` (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='管理员API Token表';
/*!40101 SET character_set_client = @saved_cs_client */;

