/*!40000 ALTER TABLE `admin_api_token` ENABLE KEYS */;
DROP TABLE IF EXISTS `admin_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_log` (
  `log_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID号',
  `log_time` int unsigned NOT NULL DEFAULT '0' COMMENT '写日志时间',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '该日志所记录的操作者id,同admin_user的user_id',
  `scope_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'legacy' COMMENT '操作作用域：admin-平台，shop-店铺，vendor-供应商，legacy-历史未标注',
  `scope_id` int unsigned NOT NULL DEFAULT '0' COMMENT '作用域ID：平台/历史为0，店铺为shop_id，供应商为vendor_id',
  `log_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理操作内容',
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '登录者登录IP',
  `request_log_id` int DEFAULT NULL COMMENT '关联的请求日志ID',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `log_time` (`log_time`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `idx_scope_type_id_time` (`scope_type`,`scope_id`,`log_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='后台管理日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `admin_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `admin_log` ENABLE KEYS */;
DROP TABLE IF EXISTS `admin_msg`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_msg` (
  `msg_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `msg_type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '消息类型：11新订单、12已付款订单、13订单完成、21商品库存预警、22商品无货、23商品下架、24商品审核通知、25商品咨询、26商品询价、31订单取消、32售后申请、33提现申请、34发票资质审核、35发票申请、36售后退款、37线下支付审核、41店铺入驻申请、42店铺资质修改、43店铺违规、44保证金预警、51系统消息、52待办任务、53意见反馈（历史兼容）、54发货提醒、55建议、56投诉、57其它反馈；15/16订单问题/订单咨询（历史兼容，不展示分类）',
  `send_time` int unsigned NOT NULL DEFAULT '0' COMMENT '消息发送时间',
  `is_readed` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '消息是否阅读,1:已阅读;0:未阅读',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '消息是否发向指定店铺',
  `admin_id` int unsigned NOT NULL DEFAULT '0' COMMENT '消息是否发向指定管理员',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '订单消息',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '订单商品消息',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '消息主题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息内容',
  `msg_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '消息链接',
  `related_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '[json]跳转数据信息',
  `is_broadcast` tinyint NOT NULL DEFAULT '1' COMMENT '是否参与语音播报: 1-播报, 0-不播报',
  `vendor_id` int DEFAULT '0' COMMENT '供应商id',
  PRIMARY KEY (`msg_id`) USING BTREE,
  KEY `msg_type` (`msg_type`) USING BTREE,
  KEY `is_readed` (`is_readed`) USING BTREE,
  KEY `shop_id` (`shop_id`) USING BTREE,
  KEY `admin_id` (`admin_id`) USING BTREE,
  KEY `order_id` (`order_id`) USING BTREE,
  KEY `goods_id` (`product_id`) USING BTREE,
  KEY `idx_vendor_id` (`vendor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='后台消息';
/*!40101 SET character_set_client = @saved_cs_client */;

