CREATE TABLE `admin_role` (
  `role_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '角色ID',
  `role_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `role_code` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '系统角色稳定标识(如 pos_cashier)',
  `role_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '描述',
  `authority_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '[JSON]权限',
  `admin_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'admin' COMMENT 'admin（平台）/ shop（店铺）/ vendor（供应商）',
  `merchant_id` int NOT NULL DEFAULT '0' COMMENT '商户id',
  `shop_id` int NOT NULL DEFAULT '0',
  `vendor_id` int NOT NULL DEFAULT '0' COMMENT '供应商ID',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否系统内置角色 0-否 1-是',
  PRIMARY KEY (`role_id`) USING BTREE,
  UNIQUE KEY `uniq_role_code_shop_type` (`role_code`,`shop_id`,`admin_type`(20)),
  KEY `user_name` (`role_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='后台角色表';
/*!40101 SET character_set_client = @saved_cs_client */;

