DROP TABLE IF EXISTS `admin_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_user` (
  `admin_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id号,管理员代码',
  `username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理员登录名',
  `admin_type` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'admin' COMMENT '管理员类型，admin:管理员，shop:店铺，suppliers:供应商，vendor:供货商',
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '手机号',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '头像',
  `password` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理员登录密码',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理员邮箱',
  `add_time` int NOT NULL DEFAULT '0' COMMENT '管理员添加时间',
  `auth_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '[JSON]管理员管理权限列表',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '绑定的会员id',
  `suppliers_id` int unsigned NOT NULL DEFAULT '0' COMMENT '供应商id',
  `role_id` int unsigned NOT NULL COMMENT '角色id',
  `merchant_id` int NOT NULL DEFAULT '0' COMMENT '商户id',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父管理员id，表明当前为子管理员',
  `menu_tag` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '[JSON]店铺存的标签',
  `order_export` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '[JSON]订单导出存的标签',
  `extra` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '[JSON]扩展信息',
  `shop_id` int NOT NULL DEFAULT '0' COMMENT '店铺id',
  `is_using` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否停用：1 是 0 否',
  `initial_password` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '初始密码',
  `is_deleted` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否删除：1 是 0 否',
  PRIMARY KEY (`admin_id`) USING BTREE,
  KEY `user_name` (`username`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='后台用户表';
