  `reply` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回复',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '添加时间',
  `tracking_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流编号',
  `logistics_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流公司',
  `return_address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '退款地址和联系电话。',
  `aftersale_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '售后原因',
  `aftersales_sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '售后编号',
  `order_id` int DEFAULT NULL COMMENT '订单id',
  `user_id` int DEFAULT NULL COMMENT '用户id',
  `refund_amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '可退款金额',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  `audit_time` int unsigned NOT NULL DEFAULT '0' COMMENT '审核时间',
  `deal_time` int unsigned NOT NULL DEFAULT '0' COMMENT '处理时间',
