DROP TABLE IF EXISTS `article_category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `article_category` (
  `article_category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `article_category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `category_sn` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类编码',
  `category_type` mediumint unsigned NOT NULL DEFAULT '1' COMMENT '分类类型 1：普通分类，2:帮助分类',
  `keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类关键字',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类描述',
  `sort_order` tinyint unsigned NOT NULL DEFAULT '50' COMMENT '分类显示顺序',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '父节点id，取值于该表article_category_id字段',
  PRIMARY KEY (`article_category_id`) USING BTREE,
  KEY `cat_type` (`category_type`) USING BTREE,
  KEY `sort_order` (`sort_order`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='文章分类信息';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `article_category` DISABLE KEYS */;
