/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `authority` (
  `authority_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id号',
  `authority_sn` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '权限编号',
  `authority_name` varchar(90) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '权限名称',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '该权限的父类ID',
  `sort_order` smallint unsigned NOT NULL DEFAULT '50' COMMENT '该权限在目录显示的的顺序,数字越大顺序越靠后,同数字,id在前的先显示',
  `is_show` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否在目录显示 1显示; 0不显示',
  `child_auth` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'JSON:子权限[{auth_name|auth_sn}]',
  `route_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '路由链接',
  `authority_ico` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '\r\nICO图标',
  `is_system` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否系统目录，是的话只能有限编辑或隐藏，不能删除',
  `admin_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'admin' COMMENT 'admin管理后台使用shop店铺使用',
  PRIMARY KEY (`authority_id`) USING BTREE,
  KEY `authority_sn` (`authority_sn`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE,
  KEY `sort_order` (`sort_order`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=100006016 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商城后台权限表';
/*!40101 SET character_set_client = @saved_cs_client */;

