DROP TABLE IF EXISTS `bargain`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bargain` (
  `bargain_id` int unsigned NOT NULL AUTO_INCREMENT,
  `bargain_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '砍一砍活动名称',
  `bargain_pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '砍一砍活动图片',
  `start_time` int unsigned NOT NULL COMMENT '砍一砍活动开始时间',
  `end_time` int unsigned NOT NULL COMMENT '砍一砍活动结束时间',
  `cut_price_limit` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '砍到多少钱',
  `cut_num_limit` int NOT NULL DEFAULT '0' COMMENT '邀请多少人砍',
  `first_cut_range` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '首次砍价范围',
  `cut_range` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '砍价范围',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品id',
  `sku_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品sku_id',
  `is_show` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否展示',
  `sort_order` smallint unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `success_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态：1:进行中，2:成功',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属店铺',
  PRIMARY KEY (`bargain_id`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='砍一砍';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `bargain` DISABLE KEYS */;
/*!40000 ALTER TABLE `bargain` ENABLE KEYS */;
DROP TABLE IF EXISTS `bargain_group`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bargain_group` (
  `group_id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  `bargain_id` int unsigned NOT NULL DEFAULT '0' COMMENT '砍一砍主键id',
  `bargain_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '砍一砍活动名',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品id',
  `sku_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品规格id',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '添加时间',
  `price` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '订单id',
  PRIMARY KEY (`group_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='砍一砍活动组';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `bargain_group` DISABLE KEYS */;
/*!40000 ALTER TABLE `bargain_group` ENABLE KEYS */;
DROP TABLE IF EXISTS `bargain_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bargain_log` (
  `log_id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  `bargain_id` int unsigned NOT NULL DEFAULT '0' COMMENT '砍一砍id',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品id',
  `sku_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品规格id',
  `cut_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00',
  `add_time` int unsigned NOT NULL COMMENT '添加时间',
  `group_id` int unsigned NOT NULL DEFAULT '0' COMMENT '砍一砍组id',
  PRIMARY KEY (`log_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='砍一砍日志';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `bargain_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `bargain_log` ENABLE KEYS */;
DROP TABLE IF EXISTS `brand`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `brand` (
  `brand_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id号',
  `brand_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌名称',
  `brand_logo` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '上传的该公司Logo图片',
  `brand_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '品牌描述',
  `site_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '否 /	品牌的网址',
  `sort_order` tinyint unsigned NOT NULL DEFAULT '50' COMMENT '品牌在前台页面的显示顺序,数字越大越靠后',
  `is_show` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '该品牌是否显示;0否1显示',
  `brand_type` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '品牌分类',
  `brand_is_hot` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否热销品牌:0,否;1,是',
  `first_word` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '首字母',
  `is_store_brand` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '(已废弃)',
  `check_status` smallint unsigned NOT NULL DEFAULT '0' COMMENT '审核状态:0,待审核;1,审核通过;2,不通过',
  `brand_en_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '品牌英文名',
  `shop_id` int NOT NULL DEFAULT '0' COMMENT '店铺id',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审核状态:0:待审核,1:审核通过,2:已拒绝',
  `reject_remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '拒绝原因',
  PRIMARY KEY (`brand_id`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE,
  KEY `first_word` (`first_word`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=223 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品品牌表';
