DROP TABLE IF EXISTS `cart`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cart` (
  `cart_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户登录ID;取自session',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品id',
  `product_sn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货号',
  `pic_thumb` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '商品缩略图',
  `market_price` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '市场价',
  `original_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '添加时的价格',
  `quantity` smallint unsigned NOT NULL DEFAULT '0' COMMENT '数量',
  `sku_id` int unsigned DEFAULT '0' COMMENT '规格ID',
  `sku_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】sku信息[{sku_id,sku_value,sku_name}]',
  `product_type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '商品类型，1：实体，2：虚拟',
  `is_checked` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否选中',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  `type` smallint unsigned NOT NULL DEFAULT '1' COMMENT '类型：1：普通购物车商品，2：拼团,3积分兑换4赠品，5砍一砍 6 虚拟 7 付费商品 8 卡密商品',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '购物车商品更新时间',
  `salesman_id` int NOT NULL DEFAULT '0' COMMENT '分销员',
  `extra_sku_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】附加属性信息[{attr_id,attr_value,attr_name}]',
  `extra_data` json DEFAULT NULL COMMENT '扩展数据',
  `change_price_data` json DEFAULT NULL COMMENT '改价数据',
  `cycle_spec_id` int unsigned DEFAULT NULL COMMENT '周期购规格ID（周期购商品时使用）',
  `redeem_card_id` int DEFAULT NULL COMMENT '兑换次卡ID（非空即兑换模式）',
  `is_wholesale_line` tinyint NOT NULL DEFAULT '0' COMMENT 'B2B批发:1=批发行 0=零售行',
  `wholesale_grade_id` int NOT NULL DEFAULT '0' COMMENT 'B2B批发:加车时等级快照(0=无)',
  PRIMARY KEY (`cart_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE,
  KEY `sku_id` (`sku_id`) USING BTREE,
  KEY `store_id` (`shop_id`) USING BTREE,
  KEY `is_checked` (`is_checked`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='购物车购物信息记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `cart` DISABLE KEYS */;
/*!40000 ALTER TABLE `cart` ENABLE KEYS */;
