DROP TABLE IF EXISTS `category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id号',
  `category_name` varchar(90) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `seo_identification` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'SEO标识',
  `keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类的关键字,可能是为了搜索',
  `category_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类描述',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '该分类的父类ID,取值于该表的cat_id字段',
  `sort_order` smallint unsigned NOT NULL DEFAULT '50' COMMENT '该分类在页面显示的顺序,数字越大顺序越靠后,同数字,id在前的先显示',
  `measure_unit` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '该分类的计量单位',
  `is_show` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否在前台页面显示 1显示; 0不显示',
  `seo_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'SEO标题',
  `short_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类短名',
  `category_pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类图片',
  `category_ico` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类图标',
  `is_hot` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否热门',
  `search_keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '搜索关键字',
  PRIMARY KEY (`category_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE,
  KEY `sort_order` (`sort_order`) USING BTREE,
  KEY `is_hot` (`is_hot`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=774 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品分类表，记录商品分类信息';
/*!40101 SET character_set_client = @saved_cs_client */;

