DROP TABLE IF EXISTS `comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comment` (
  `comment_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '用户评论的自增id ',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '发表该评论的用户的用户id,取值user的user_id ',
  `username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评论该文章或商品的人的名称,取值users的user_name ',
  `is_anonymous` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否匿名评价；0-否，1-是',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员头像',
  `product_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '商品id',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '订单id',
  `order_item_id` int unsigned NOT NULL DEFAULT '0' COMMENT '订单商品itemId',
  `comment_rank` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '星级，5代表5星 ',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '评论的内容',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '评论的时间',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态，0：待审核，1：审核通过，2：无效',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '是否为回复',
  `usefull` int unsigned NOT NULL DEFAULT '0' COMMENT '评价有用',
  `useless` int unsigned NOT NULL DEFAULT '0' COMMENT '评价无用',
  `comment_tag` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】标签[string]',
  `show_pics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】晒单图片[{pic_thumb,pic_url}]',
  `is_recommend` tinyint unsigned DEFAULT '0' COMMENT '是否推荐',
  `is_top` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否置顶',
  `is_showed` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否已晒单',
  `is_default` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '系统默认评价',
  `sort_order` mediumint unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属店铺',
  PRIMARY KEY (`comment_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE,
  KEY `order_item_id` (`order_item_id`) USING BTREE,
  KEY `is_default` (`is_default`) USING BTREE,
  KEY `sort_order` (`sort_order`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `is_showed` (`is_showed`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户对文章和产品的评论列表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `comment` DISABLE KEYS */;
/*!40000 ALTER TABLE `comment` ENABLE KEYS */;
