DROP TABLE IF EXISTS `credit_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `credit_order` (
  `credit_order_id` int NOT NULL AUTO_INCREMENT COMMENT '账期订单ID',
  `order_id` int NOT NULL COMMENT '订单ID',
  `order_sn` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `user_id` int NOT NULL COMMENT '会员ID',
  `credit_user_id` int NOT NULL COMMENT '授信会员ID',
  `credit_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '账期支付金额（单位：元）',
  `settlement_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '结算状态：0-未结算，1-已结算，2-已取消，3-退款中',
  `settlement_id` int DEFAULT NULL COMMENT '结算记录ID',
  `settlement_sn` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '回款流水单号',
  `order_time` bigint DEFAULT NULL COMMENT '下单时间（秒级时间戳）',
  `settlement_time` bigint DEFAULT NULL COMMENT '结算时间（秒级时间戳）',
  `create_time` bigint DEFAULT NULL COMMENT '创建时间（秒级时间戳）',
  `update_time` bigint DEFAULT NULL COMMENT '更新时间（秒级时间戳）',
  PRIMARY KEY (`credit_order_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_credit_user_id` (`credit_user_id`),
  KEY `idx_settlement_status` (`settlement_status`),
  KEY `idx_order_time` (`order_time`),
  KEY `idx_settlement_id` (`settlement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='账期支付订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `credit_order` DISABLE KEYS */;
/*!40000 ALTER TABLE `credit_order` ENABLE KEYS */;
DROP TABLE IF EXISTS `credit_settlement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `credit_settlement` (
  `settlement_id` int NOT NULL AUTO_INCREMENT COMMENT '结算ID',
  `settlement_sn` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回款流水单号',
  `user_id` int NOT NULL COMMENT '会员ID',
  `credit_user_id` int NOT NULL COMMENT '授信会员ID',
  `settlement_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '结算金额（单位：元）',
  `order_count` int NOT NULL DEFAULT '0' COMMENT '结算订单数',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '备注',
  `settlement_time` bigint DEFAULT NULL COMMENT '结算时间（秒级时间戳）',
  `settlement_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '结算状态：1-已结算，2-已撤销',
  `cancel_time` bigint DEFAULT NULL COMMENT '撤销时间（秒级时间戳）',
  `cancel_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '撤销原因',
  `operator_id` int DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '操作人名称',
  `create_time` bigint DEFAULT NULL COMMENT '创建时间（秒级时间戳）',
  `update_time` bigint DEFAULT NULL COMMENT '更新时间（秒级时间戳）',
  PRIMARY KEY (`settlement_id`),
  UNIQUE KEY `uk_settlement_sn` (`settlement_sn`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_credit_user_id` (`credit_user_id`),
  KEY `idx_settlement_time` (`settlement_time`),
  KEY `idx_settlement_status` (`settlement_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='账期结算表';
/*!40101 SET character_set_client = @saved_cs_client */;

