/*!40000 ALTER TABLE `credit_settlement` ENABLE KEYS */;
DROP TABLE IF EXISTS `credit_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `credit_user` (
  `credit_user_id` int NOT NULL AUTO_INCREMENT COMMENT '授信会员ID',
  `user_id` int NOT NULL COMMENT '会员ID',
  `credit_limit` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '信用额度（单位：元）',
  `used_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '已使用额度（单位：元）',
  `available_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '可用额度（单位：元）',
  `settlement_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '结算账期类型：1-月结30天，2-季结90天',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0-禁用，1-启用',
  `period_start_time` bigint DEFAULT NULL COMMENT '当前结算周期起点（秒级时间戳），结算清空后重置',
  `create_time` bigint DEFAULT NULL COMMENT '创建时间（秒级时间戳）',
  `update_time` bigint DEFAULT NULL COMMENT '更新时间（秒级时间戳）',
  PRIMARY KEY (`credit_user_id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='授信会员表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `credit_user` DISABLE KEYS */;
/*!40000 ALTER TABLE `credit_user` ENABLE KEYS */;
DROP TABLE IF EXISTS `crons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `crons` (
  `cron_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '计划任务ID',
  `cron_sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '计划任务编号',
  `cron_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `cron_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '描述',
  `last_runtime` int NOT NULL DEFAULT '0' COMMENT '上次执行时间',
  `next_runtime` int NOT NULL DEFAULT '0' COMMENT '下次执行时间',
  `cron_type` tinyint NOT NULL DEFAULT '0' COMMENT '定时方式：1：每年，2：每月，3：每周，4：每天，5：每小时，6：每分钟\n11：每隔N年，12：每隔N月，13：每隔N周，14：每隔N天，15：每隔N小时，16：每隔N分钟',
  `cron_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '[JSON]存对应cron_type数据',
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否开启',
  `just_once` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否仅执行一次',
  `white_ip_list` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '白名单',
  PRIMARY KEY (`cron_id`) USING BTREE,
  KEY `nextime` (`next_runtime`) USING BTREE,
  KEY `enable` (`is_enabled`) USING BTREE,
  KEY `cron_code` (`cron_sn`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='定时任务表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `crons` DISABLE KEYS */;
/*!40000 ALTER TABLE `crons` ENABLE KEYS */;
DROP TABLE IF EXISTS `currency`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `currency` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '币种名称',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '币种符号',
  `is_default` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否默认：1 是 0 否',
  `rate` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '汇率',
  `code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '国际通用代号(ISO 4217，如 USD/EUR/CNY)，汇率源匹配依据',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='货币管理表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `currency` DISABLE KEYS */;
/*!40000 ALTER TABLE `currency` ENABLE KEYS */;
DROP TABLE IF EXISTS `decorate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `decorate` (
  `decorate_id` int NOT NULL AUTO_INCREMENT,
  `decorate_title` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '模板名称',
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '已发布的-页面模块数据',
  `draft_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '草稿-页面模块数据',
  `decorate_type` tinyint DEFAULT '1' COMMENT '页面类型 1:h5  2:PC ',
  `page_type` tinyint NOT NULL DEFAULT '1' COMMENT '页面类型:1首页 2个人中心 3活动 4分类 5登录 6搜索 8商品详情页',
  `is_home` int DEFAULT '0' COMMENT '是否是首页',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属店铺',
  `status` tinyint(1) DEFAULT '0' COMMENT '1:发布 ,0:未发布   ',
  `update_time` int DEFAULT '0' COMMENT '更新时间',
  `locale_id` int DEFAULT '0' COMMENT '关联语言默认为0',
  `parent_id` int DEFAULT '0' COMMENT '父级id',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `binded_h5_id` int DEFAULT '0' COMMENT '绑定的h5页面id（decorate_type = 3 生效）',
  `share_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '分享信息（JSON：shareTitle/shareDesc/shareImage）',
  PRIMARY KEY (`decorate_id`) USING BTREE,
  KEY `page_type` (`decorate_type`) USING BTREE,
  KEY `page_id` (`is_home`) USING BTREE,
  KEY `store_id` (`shop_id`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='装修页面表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `decorate` DISABLE KEYS */;
