/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `decorate_share` (
  `share_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID号',
  `share_sn` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分享sn码',
  `share_token` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '分享验证token',
  `decorate_id` int NOT NULL DEFAULT '0' COMMENT '装修页面id',
  `valid_time` int NOT NULL DEFAULT '0' COMMENT 'token有效时间',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '添加时间',
  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`share_id`) USING BTREE,
  KEY `share_sn` (`share_sn`) USING BTREE,
  KEY `share_token` (`share_token`) USING BTREE,
  KEY `decorate_id` (`decorate_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='装修页面分享表';
