DROP TABLE IF EXISTS `delivery_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `delivery_order` (
  `delivery_order_id` int NOT NULL AUTO_INCREMENT COMMENT '派送订单ID',
  `delivery_order_sn` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '派送订单编号',
  `order_id` int NOT NULL COMMENT '关联商城订单ID',
  `order_sn` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联商城订单编号',
  `shop_id` int NOT NULL COMMENT '门店ID',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '类型：1-配送订单，2-服务订单',
  `dispatch_mode` tinyint NOT NULL DEFAULT '1' COMMENT '派单模式：1-抢单模式，2-手动派单',
  `status` tinyint NOT NULL DEFAULT '10' COMMENT '状态：10-待派发，20-待取货/待服务，30-配送中/服务中，40-已完成，50-已取消',
  `staff_id` int DEFAULT NULL COMMENT '配送员/服务员ID',
  `staff_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '配送员/服务员姓名',
  `staff_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '配送员/服务员电话',
  `consignee` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人/服务对象姓名',
  `mobile` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人/服务对象电话',
  `address` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '配送地址/服务地址',
  `region_names` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地区名称（省市区）',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '配送地址/服务地址纬度',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '配送地址/服务地址经度',
  `pickup_region_names` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取货地址（门店地址） 省市区',
  `pickup_address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取货地址（门店地址）',
  `pickup_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取货电话',
  `pickup_latitude` decimal(10,6) DEFAULT NULL COMMENT '取货地址纬度',
  `pickup_longitude` decimal(10,6) DEFAULT NULL COMMENT '取货地址经度',
  `service_time` int DEFAULT NULL COMMENT '预约服务时间（Unix时间戳）',
  `order_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单金额',
  `buyer_note` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '买家备注',
  `dispatch_time` int DEFAULT NULL COMMENT '派单时间（Unix时间戳）',
  `grab_time` int DEFAULT NULL COMMENT '抢单时间（Unix时间戳）',
  `pickup_time` int DEFAULT NULL COMMENT '取货时间/开始服务时间（Unix时间戳）',
  `complete_time` int DEFAULT NULL COMMENT '完成时间（Unix时间戳）',
  `cancel_time` int DEFAULT NULL COMMENT '取消时间（Unix时间戳）',
  `cancel_reason` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取消原因',
  `cancel_by` tinyint DEFAULT NULL COMMENT '取消方：1-配送员/服务员，2-后台管理员，3-系统',
  `pickup_photo` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取货照片（JSON数组）',
  `complete_photo` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '完成照片（JSON数组）',
  `before_service_photo` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '服务前照片（JSON数组）',
  `after_service_photo` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '服务后照片（JSON数组）',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间（Unix时间戳）',
  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间（Unix时间戳）',
  `is_delete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除：0-否，1-是',
  `carrier_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '运力类型 1自建配送 2美团配送',
  `mt_delivery_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '合作方配送单号（发给美团的 delivery_id，本系统唯一）',
  `mt_peisong_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '美团配送单号（美团返回的 mt_peisong_id）',
  `mt_status` smallint DEFAULT NULL COMMENT '美团订单状态 0待调度 20已接单 30已取货 50已送达 99已取消',
  `mt_delivery_service_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '美团配送服务代码（飞速达/快速达/及时达等）',
  `mt_cancel_code` int DEFAULT NULL COMMENT '美团取消/异常代码',
  `mt_distance` int DEFAULT NULL COMMENT '美团配送距离（米）',
  `mt_fee` decimal(10,2) DEFAULT NULL COMMENT '美团配送费（元）',
  PRIMARY KEY (`delivery_order_id`),
  UNIQUE KEY `uk_delivery_order_sn` (`delivery_order_sn`),
  UNIQUE KEY `uk_order_id` (`order_id`),
  KEY `idx_shop_id` (`shop_id`),
  KEY `idx_staff_id` (`staff_id`),
  KEY `idx_status` (`status`),
  KEY `idx_type` (`type`),
  KEY `idx_dispatch_mode` (`dispatch_mode`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_shop_status` (`shop_id`,`status`),
  KEY `idx_staff_status` (`staff_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='派送订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `delivery_order` DISABLE KEYS */;
/*!40000 ALTER TABLE `delivery_order` ENABLE KEYS */;
DROP TABLE IF EXISTS `distribution_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `distribution_log` (
  `log_id` int unsigned NOT NULL AUTO_INCREMENT,
  `order_id` mediumint NOT NULL DEFAULT '0' COMMENT '订单编号',
  `add_time` int NOT NULL DEFAULT '0' COMMENT '添加时间',
  `level` tinyint NOT NULL DEFAULT '0' COMMENT '级别',
  `user_id` mediumint NOT NULL DEFAULT '0' COMMENT '会员id',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `point` int NOT NULL DEFAULT '0' COMMENT '积分',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1:分成,2:撤消',
  `log_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '备注',
  `is_returned` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否撤回',
  PRIMARY KEY (`log_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分佣日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `distribution_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `distribution_log` ENABLE KEYS */;
DROP TABLE IF EXISTS `e_card`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_card` (
  `card_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '卡券分组id',
  `group_id` int unsigned NOT NULL COMMENT '卡券分组id',
  `card_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡号',
  `card_pwd` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡号密码',
  `is_use` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0:未使用,1:已使用',
  `order_id` int NOT NULL DEFAULT '0' COMMENT '订单id',
  `order_item_id` int NOT NULL DEFAULT '0' COMMENT '订单item_id',
  `add_time` int unsigned DEFAULT '0' COMMENT '添加时间',
  `up_time` int unsigned DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`card_id`) USING BTREE,
  KEY `group_id` (`group_id`) USING BTREE,
  KEY `order_id` (`order_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1216 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='电子卡券表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `e_card` DISABLE KEYS */;
/*!40000 ALTER TABLE `e_card` ENABLE KEYS */;
DROP TABLE IF EXISTS `e_card_group`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_card_group` (
  `group_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '卡券分组id',
  `group_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分组名称',
  `shop_id` int unsigned NOT NULL COMMENT '店铺id',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '备注',
  `is_use` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0:不使用,1:使用',
  `add_time` int unsigned DEFAULT '0' COMMENT '添加时间',
  `up_time` int unsigned DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`group_id`) USING BTREE
