DROP TABLE IF EXISTS `feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `feedback` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '反馈ID',
  `parent_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '是否为回复',
  `user_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '反馈会员id',
  `username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '反馈会员名',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '邮箱',
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '手机号',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '反馈标题',
  `type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '类型',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态，0：待回复，1：已回复，2：无效',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '内容',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '时间',
  `feedback_pics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】图片上传',
  `product_id` int unsigned DEFAULT '0' COMMENT '商品ID',
  `order_id` int unsigned DEFAULT '0' COMMENT '订单ID',
  `complaint_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '投诉项',
  `shop_id` int unsigned DEFAULT '0' COMMENT '店铺id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE,
  KEY `idx_feedback_shop_type_parent_id` (`shop_id`,`type`,`parent_id`,`id`),
  KEY `idx_feedback_product_shop_parent_type` (`product_id`,`shop_id`,`parent_id`,`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员留言表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `feedback` DISABLE KEYS */;
/*!40000 ALTER TABLE `feedback` ENABLE KEYS */;
