DROP TABLE IF EXISTS `gallery_pic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gallery_pic` (
  `pic_id` int unsigned NOT NULL AUTO_INCREMENT,
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  `gallery_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '相册id',
  `pic_ower_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '操作人员id',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片地址',
  `pic_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片名称',
  `pic_thumb` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '缩略图',
  `add_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '添加时间',
  `vendor_id` int NOT NULL DEFAULT '0' COMMENT '供应商 ID',
  `hidden` tinyint DEFAULT NULL COMMENT '0 或者 null 不隐藏 1  表示隐藏',
  `pic_width` int DEFAULT NULL COMMENT '图片宽度',
  `pic_height` int DEFAULT NULL COMMENT '图片高度',
  `pic_size` bigint DEFAULT NULL COMMENT '图片大小（字节）',
  `file_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文件格式（如png、jpg、webp）',
  `pic_sort` int DEFAULT '0' COMMENT '手动排序值',
  `source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'upload' COMMENT '来源：upload=本地上传, external=外部直链',
  PRIMARY KEY (`pic_id`) USING BTREE,
  KEY `gallery_id` (`gallery_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1083 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='相册图片表';
