/*!40000 ALTER TABLE `gallery_pic` ENABLE KEYS */;
DROP TABLE IF EXISTS `gallery_video`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gallery_video` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户id',
  `parent_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '父级id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `sort` mediumint unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '添加时间',
  `add_user_id` mediumint unsigned NOT NULL DEFAULT '1' COMMENT '创建人id',
  `vendor_id` int NOT NULL DEFAULT '0' COMMENT '供应商id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_shop_parent` (`shop_id`,`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='视频相册文件夹';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `gallery_video` DISABLE KEYS */;
/*!40000 ALTER TABLE `gallery_video` ENABLE KEYS */;
DROP TABLE IF EXISTS `gallery_video_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gallery_video_info` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户id',
  `gallery_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '相册id',
  `video_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '视频地址',
  `video_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '视频名称',
  `video_cover` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '视频封面',
  `description` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '视频简介',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '添加时间',
  `add_user_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '创建人id',
  `format` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '视频格式后缀',
  `video_first_frame` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '视频封面（第一帧）',
  `duration` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '时长',
  `size` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '大小',
  `vendor_id` int NOT NULL DEFAULT '0' COMMENT '供应商id',
  `source` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'upload' COMMENT '来源：upload=本地上传, external=外部直链',
  PRIMARY KEY (`id`) USING BTREE
