  `shop_id` int NOT NULL DEFAULT '0' COMMENT '店铺id',
  `user_from` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源',
  PRIMARY KEY (`id`) USING BTREE
