DROP TABLE IF EXISTS `logistics_api_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `logistics_api_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int DEFAULT '0' COMMENT '商城订单号',
  `provider_type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '实际创建面单的物流服务商：0未知，1快递鸟，2快递100',
  `order_code` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '快递订单编号',
  `logistic_code` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '物流单号',
  `add_time` int DEFAULT '0' COMMENT '发起时间',
  `print_template` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '返回模板',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `order_id` (`order_id`) USING BTREE,
  KEY `logistic_code` (`logistic_code`) USING BTREE,
  KEY `order_code` (`order_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='快递接口调用日志';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `logistics_api_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `logistics_api_log` ENABLE KEYS */;
DROP TABLE IF EXISTS `logistics_company`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `logistics_company` (
  `logistics_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增id号',
  `logistics_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配送方式的快递公司代号',
  `logistics_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配送方式名称',
  `logistics_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配送方式描述',
  `sort_order` tinyint unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `is_show` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否展示',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `customer_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '客户编码',
  `customer_pwd` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '密码',
  `month_code` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '月结号',
  `send_site` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '网点编码',
  `send_staff` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '网点名称',
  `exp_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '快递业务类型',
  `api_logistics_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '无服务调用物流编号',
  `kuaidi100_code` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100快递公司编码（小写，如 shunfeng/yuantong；留空则走内置映射）',
  `kuaidi100_partner_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-电子面单账户/月结账号 partnerId',
  `kuaidi100_partner_key` varchar(200) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-电子面单密码 partnerKey',
  `kuaidi100_partner_secret` varchar(200) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-电子面单密钥 partnerSecret',
  `kuaidi100_net` varchar(120) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-收件网点名 net',
  `kuaidi100_check_man` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-承载快递员名 checkMan',
  `kuaidi100_exp_type` varchar(40) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-产品类型 expType',
  `kuaidi100_temp_id` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-主单模板ID tempId（IMAGE/HTML/CLOUD 网点面单必填）',
  `kuaidi100_child_temp_id` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-子单模板ID childTempId',
  `kuaidi100_back_temp_id` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-回单模板ID backTempId',
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用：1启用，0禁用',
  PRIMARY KEY (`logistics_id`) USING BTREE,
  KEY `shipping_code` (`logistics_code`) USING BTREE,
  KEY `shop_id` (`shop_id`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2149 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='配送方式配置信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `logistics_company` DISABLE KEYS */;
