/*!40000 ALTER TABLE `logistics_company` ENABLE KEYS */;
DROP TABLE IF EXISTS `logistics_company_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `logistics_company_config` (
  `config_id` int NOT NULL AUTO_INCREMENT COMMENT '配置ID',
  `logistics_id` int NOT NULL COMMENT '物流公司ID（关联 logistics_company.logistics_id）',
  `shop_id` int NOT NULL DEFAULT '0' COMMENT '店铺ID（平台=0，店铺/门店>0）',
  `vendor_id` int NOT NULL DEFAULT '0' COMMENT '供应商ID（非供应商=0，供应商>0）',
  `customer_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '客户编码',
  `customer_pwd` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '密码',
  `month_code` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '月结号',
  `send_site` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '网点编码',
  `send_staff` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '网点名称',
  `exp_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '快递业务类型',
  `kuaidi100_partner_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-电子面单账户/月结账号 partnerId',
  `kuaidi100_partner_key` varchar(200) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-电子面单密码 partnerKey',
  `kuaidi100_partner_secret` varchar(200) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-电子面单密钥 partnerSecret',
  `kuaidi100_net` varchar(120) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-收件网点名 net',
  `kuaidi100_check_man` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-承载快递员名 checkMan',
  `kuaidi100_exp_type` varchar(40) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-产品类型 expType',
  `kuaidi100_temp_id` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-主单模板ID tempId（IMAGE/HTML/CLOUD 网点面单必填）',
  `kuaidi100_child_temp_id` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-子单模板ID childTempId',
  `kuaidi100_back_temp_id` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递100电子面单-回单模板ID backTempId',
  `sort_order` int DEFAULT '50' COMMENT '排序',
