/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lottery_activity` (
  `activity_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '活动ID',
  `activity_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动名称',
  `start_time` int unsigned NOT NULL DEFAULT '0' COMMENT '活动开始时间(秒级时间戳)',
  `end_time` int unsigned NOT NULL DEFAULT '0' COMMENT '活动结束时间(秒级时间戳)',
  `cost_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '抽奖参与条件:0-无限制(免费),1-消耗积分',
  `cost_points` int unsigned NOT NULL DEFAULT '0' COMMENT '每次抽奖消耗积分',
  `daily_limit` int unsigned NOT NULL DEFAULT '0' COMMENT '每日最大抽奖次数(0表示不限制)',
  `total_limit` int unsigned NOT NULL DEFAULT '0' COMMENT '最大抽奖次数(0表示不限制)',
  `win_limit` int unsigned NOT NULL DEFAULT '0' COMMENT '每人最多中奖次数(0表示不限制)',
  `decorate_config` json DEFAULT NULL COMMENT '装修配置(JSON格式):bgImage,bgColor,showWinnerList,activityRules',
  `grid_config` json DEFAULT NULL COMMENT '九宫格配置(JSON数组):position,prizeId,probability',
  `no_win_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '谢谢惠顾' COMMENT '未中奖名称(未选择奖品的位置显示)',
  `no_win_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '未中奖图片URL(未选择奖品的位置显示)',
  `no_win_tips` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '很遗憾，再接再厉！' COMMENT '未中奖提示语(弹窗显示)',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺ID(平台为0)',
  `is_delete` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否删除:0-否,1-是(软删除)',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间(秒级时间戳)',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间(秒级时间戳)',
  PRIMARY KEY (`activity_id`) USING BTREE,
  KEY `idx_time` (`start_time`,`end_time`) USING BTREE,
  KEY `idx_shop_id` (`shop_id`) USING BTREE,
  KEY `idx_is_delete` (`is_delete`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='抽奖活动表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `lottery_activity` DISABLE KEYS */;
INSERT INTO `lottery_activity` VALUES (1,'2026年开年抽奖活动',1767628800,1798732800,1,10,0,0,0,'{\"bgColor\": \"rgb(255, 140, 0)\", \"bgImage\": \"https://oss.tigshop.com/img/gallery/202512/1766469537jXrMsUPDXoszzk0KCC.jpeg\", \"activityRules\": \"1.本活动商城所有用户均可参与；\\n2.每次参与需消耗10积分,每天无限次参加；\\n3.当积分余额不足时,可在商城通过订单、签到等方式获得；\\n4.实物奖品将在中奖后的3-5个工作日内发货,请耐心等待；\\n5.优惠券在中奖后会实时到账,请至会员中心“优惠券处查看。\", \"showWinnerList\": 1}','[{\"prizeId\": 1, \"position\": 1, \"probability\": 12.5}, {\"prizeId\": 2, \"position\": 2, \"probability\": 12.5}, {\"prizeId\": 3, \"position\": 3, \"probability\": 12.5}, {\"prizeId\": 4, \"position\": 4, \"probability\": 12.5}, {\"prizeId\": 5, \"position\": 5, \"probability\": 12.5}, {\"prizeId\": 6, \"position\": 6, \"probability\": 12.5}, {\"prizeId\": 7, \"position\": 7, \"probability\": 12.5}, {\"prizeId\": null, \"position\": 8, \"probability\": 12.5}]','谢谢参与','https://oss.tigshop.com/img/gallery/202512/1766467150H93CwsgU07PQfSqwj4.jpeg','很遗憾没有抽中',0,0,1767678559,1767773810);
