  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `total_count` int unsigned NOT NULL DEFAULT '0' COMMENT '累计抽奖次数',
  `win_count` int unsigned NOT NULL DEFAULT '0' COMMENT '累计中奖次数',
  `today_count` int unsigned NOT NULL DEFAULT '0' COMMENT '今日抽奖次数',
  `today_date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '今日日期(YYYY-MM-DD)',
  `last_lottery_time` int unsigned DEFAULT NULL COMMENT '最后抽奖时间(秒级时间戳)',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间(秒级时间戳)',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间(秒级时间戳)',
  PRIMARY KEY (`stat_id`) USING BTREE,
  UNIQUE KEY `uk_activity_user` (`activity_id`,`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户抽奖统计表';
