DROP TABLE IF EXISTS `merchant_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `merchant_account` (
  `account_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '账号ID',
  `merchant_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '商户id',
  `account_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '提现账号类型，1：银行卡，2：支付宝，3：微信',
  `account_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '姓名',
  `account_no` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '银行卡号或账号',
  `bank_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行名称',
  `add_time` int DEFAULT '0' COMMENT '添加时间',
  `bank_branch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '分行名称',
  `shop_id` int DEFAULT NULL COMMENT '店铺ID',
  PRIMARY KEY (`account_id`) USING BTREE,
  KEY `account_type` (`account_type`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商家账户表';
/*!40101 SET character_set_client = @saved_cs_client */;

