DROP TABLE IF EXISTS `merchant_application`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `merchant_application` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '进件申请ID',
  `shop_id` bigint NOT NULL COMMENT '店铺ID',
  `applicant_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'SHOP' COMMENT '申请主体类型:SHOP店铺/门店 VENDOR供应商',
  `applicant_id` bigint NOT NULL DEFAULT '0' COMMENT '申请主体ID:SHOP=shopId VENDOR=vendorId',
  `applicant_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请主体名称(店铺名/供应商名,冗余展示)',
  `pay_channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'WECHAT' COMMENT '支付渠道',
  `business_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务申请编号(幂等键)',
  `applyment_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '微信申请单号',
  `organization_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '组织类型',
  `merchant_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户名称',
  `contact_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `contact_phone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话',
  `id_card_number_enc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '身份证号(加密)',
  `bank_account_enc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '银行账号(加密)',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态:DRAFT草稿/PENDING_REVIEW平台待审核/SUBMITTED已提交/CHECKING资料校验中/AUDITING审核中/ACCOUNT_NEED_VERIFY待账户验证/NEED_SIGN待签约/FINISH完成/REJECTED已驳回',
  `sub_mch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '成功后返回的子商户号',
  `sign_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '签约链接',
  `reject_reason` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驳回原因',
  `audit_admin_id` int NOT NULL DEFAULT '0' COMMENT '审核人ID(平台管理员)',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `request_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '提交请求快照(脱敏JSON)',
  `is_del` int NOT NULL DEFAULT '0' COMMENT '逻辑删除:0未删 非0已删',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `modify_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_business_code` (`business_code`),
  KEY `idx_shop_id` (`shop_id`),
  KEY `idx_status` (`status`),
  KEY `idx_applicant` (`applicant_type`,`applicant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='商户进件申请';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `merchant_application` DISABLE KEYS */;
/*!40000 ALTER TABLE `merchant_application` ENABLE KEYS */;
DROP TABLE IF EXISTS `merchant_application_media`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `merchant_application_media` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '进件媒体ID',
  `application_id` bigint NOT NULL DEFAULT '0' COMMENT '进件申请ID，0表示未绑定',
  `uploader_admin_id` int NOT NULL COMMENT '上传后台账号ID',
  `applicant_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请主体类型:SHOP/VENDOR',
  `applicant_id` bigint NOT NULL DEFAULT '0' COMMENT '申请主体ID',
  `media_role` tinyint NOT NULL DEFAULT '0' COMMENT '媒体角色:0未绑定 1营业执照 2身份证人像面 3身份证国徽面',
  `initial_media_id_hash` char(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '初始MediaID的SHA-256摘要',
  `object_name` varchar(512) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '私有OSS随机对象键',
  `file_ext` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件扩展名',
  `content_type` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件MIME类型',
  `file_size` bigint NOT NULL DEFAULT '0' COMMENT '文件大小，单位字节',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态:0上传中 1临时 2已绑定 3待删除 4已删除',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '删除重试次数',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次补偿时间',
  `expire_time` datetime DEFAULT NULL COMMENT '当前生命周期到期时间',
  `last_error_code` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '脱敏错误分类',
  `is_del` int NOT NULL DEFAULT '0' COMMENT '逻辑删除:0未删 非0已删',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `modify_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_uploader_media_hash` (`uploader_admin_id`,`initial_media_id_hash`),
  KEY `idx_application_role_status` (`application_id`,`media_role`,`status`),
  KEY `idx_cleanup` (`status`,`expire_time`,`next_retry_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='商户进件媒体元数据';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `merchant_application_media` DISABLE KEYS */;
/*!40000 ALTER TABLE `merchant_application_media` ENABLE KEYS */;
DROP TABLE IF EXISTS `merchant_apply`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `merchant_apply` (
  `merchant_apply_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL COMMENT '用户id',
  `add_time` int DEFAULT '0' COMMENT '添加时间',
  `shop_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '店铺名称',
  `status` tinyint DEFAULT '1' COMMENT '1待审核10审核通过20审核未通过',
  `type` tinyint DEFAULT '1' COMMENT '1个人2企业',
  `contact_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '联系人名称',
  `contact_mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '联系人手机',
  `audit_time` int DEFAULT '0' COMMENT '审核时间',
  `audit_admin_id` int DEFAULT '0' COMMENT '审核管理员ID(admin_user.admin_id)',
  `shop_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '申请资料shop信息json',
  `base_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '申请资料基本信息json',
  `merchant_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '申请资料的商户信息json',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '企业名称',
  `corporate_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '申请主体信息',
  `audit_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '审核备注',
  PRIMARY KEY (`merchant_apply_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商家入驻表';
/*!40101 SET character_set_client = @saved_cs_client */;

