DROP TABLE IF EXISTS `merchant_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `merchant_user` (
  `merchant_user_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT '0' COMMENT '前台用户id',
  `admin_user_id` int DEFAULT '0' COMMENT '后台用户id',
  `merchant_id` int DEFAULT '0' COMMENT '商户id',
  `is_admin` tinyint DEFAULT '0' COMMENT '是否管理员1是0不是',
  PRIMARY KEY (`merchant_user_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `admin_user_id` (`admin_user_id`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商户用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `merchant_user` DISABLE KEYS */;
