DROP TABLE IF EXISTS `message_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `message_type` (
  `message_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '通知类型',
  `describe` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '通知描述',
  `send_type` tinyint(1) DEFAULT '1' COMMENT '发送类型  1会员 2商家',
  `is_wechat` tinyint(1) DEFAULT '0' COMMENT '是否支持微信公众号',
  `is_mini_program` tinyint(1) DEFAULT '0' COMMENT '是否支持小程序',
  `is_message` tinyint(1) DEFAULT '0' COMMENT '是否支持站内信',
  `is_msg` tinyint(1) DEFAULT '0' COMMENT '是否支持短信',
  `is_app` tinyint(1) DEFAULT '0' COMMENT '是否支付app',
  `is_ding` tinyint(1) DEFAULT '0' COMMENT '是否支持钉钉',
  `add_time` int DEFAULT '0' COMMENT '添加时间',
  `is_wx_work` tinyint(1) NOT NULL DEFAULT '-1' COMMENT '是否支持企业微信',
  `is_mail` tinyint(1) NOT NULL DEFAULT '-1' COMMENT '是否支持邮件',
  PRIMARY KEY (`message_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='消息类型';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `message_type` DISABLE KEYS */;
