DROP TABLE IF EXISTS `mobile_cat_nav`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mobile_cat_nav` (
  `mobile_cat_nav_id` int unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '选择分类',
  `cat_color` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类颜色（颜色选择器）',
  `child_cat_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '[JSON]推荐子分类（多选）',
  `brand_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '推荐品牌',
  `is_show` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否显示：1显示，0不显示',
  `img_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类banner字符串，英文符号''｜'' 分割',
  `sort_order` smallint unsigned NOT NULL DEFAULT '50' COMMENT '在页面显示的顺序,数字越大顺序越靠后,同数字,id在前的先显示',
  `cat_name_alias` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '自定义分类名',
  PRIMARY KEY (`mobile_cat_nav_id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='手机分类';
/*!40101 SET character_set_client = @saved_cs_client */;

