DROP TABLE IF EXISTS `order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order` (
  `order_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `order_sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号,唯一',
  `user_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '用户id,同users的user_id',
  `parent_order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '父订单id',
  `parent_order_sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '父订单号',
  `order_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '订单的状态：0 待确定，待支付 1 已确定，待发货 2处理中，已发货 3 已取消 4 无效 5 已完成',
  `shipping_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '商品配送情况;0未发货,1已发货,2已收货,4退货',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '支付状态：0未支付 1支付中 2已支付 3退款中 4 已退款',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '订单生成时间',
  `consignee` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人的姓名,用户页面填写,默认取值表user_address',
  `address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '详细地址',
  `region_ids` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '【JSON】地址id，number[]',
  `region_names` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '【JSON】地址name, string[]',
  `address_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】收货人信息',
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人的手机',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人的Email',
  `buyer_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家备注',
  `admin_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商家备注，仅商家可见',
  `shipping_method` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '发货方式：1：物流，2：商家自提，3：无需配送',
  `logistics_id` int unsigned NOT NULL DEFAULT '0' COMMENT '快递公司id/为0则表示商家配送或无需配送',
  `logistics_provider` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '物流服务商：0历史未知或不适用，1快递鸟，2快递100',
  `logistics_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '具体物流公司名称/商家配送/无需配送',
  `shipping_type_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '配送类型id',
  `shipping_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配送类型名称',
  `tracking_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `shipping_time` int unsigned NOT NULL DEFAULT '0' COMMENT '订单配送时间',
  `received_time` int unsigned NOT NULL DEFAULT '0' COMMENT '订单收货时间',
  `pay_type_id` smallint unsigned NOT NULL DEFAULT '0' COMMENT '支付类型:1,在线支付（微信、支付等）;2,货到付款（支持先发货，后付款）;3,线下支付',
  `pay_time` int unsigned NOT NULL DEFAULT '0' COMMENT '订单支付时间',
  `use_points` int unsigned NOT NULL DEFAULT '0' COMMENT '使用的积分的数量',
  `is_need_commisson` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否需要分佣',
  `distribution_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已分销分成',
  `referrer_user_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '推广人userId',
  `is_del` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否删除',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  `is_store_splited` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否已按店铺拆分:0,否;1,是',
  `is_valid` tinyint(1) NOT NULL DEFAULT '1' COMMENT '订单是否有效:1有效;0无效(支付后拆单父订单)',
  `comment_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否已评价',
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单总金额（商品总价 + 运费等 - 优惠券 - 各种优惠活动）',
  `paid_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '已支付金额(包含使用余额+线上支付金额+线下支付金额)',
  `unpaid_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '未付款金额（计算方式为：total_amount - paid_amount）',
  `unrefund_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '未退款金额（一般出现在订单取消或修改金额、商品后）',
  `product_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品的总金额',
