  `points_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '使用积分金额',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '参加优惠活动金额，如折扣、满减等',
  `balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '使用余额金额',
  `credit_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '账期支付金额（单位：元）',
  `is_credit_order` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否账期订单：0-否，1-是',
  `online_paid_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '线上支付金额（支付宝、微信等）',
  `offline_paid_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '线下支付金额（银行汇款等）',
  `service_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '服务费',
  `shipping_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '配送费用',
  `invoice_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '发票费用',
  `order_extension` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '【JSON】记录订单使用的优惠券、优惠活动、不同店铺配送等的具体细节信息',
  `order_source` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '下单来源设备，APP|PC|H5|微信公众号|微信小程序',
  `invoice_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】发票信息',
  `out_trade_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '订单支付平台单号',
  `is_settlement` tinyint DEFAULT '0' COMMENT '是否结算0未结算1已结算',
  `is_exchange_order` tinyint(1) DEFAULT '0' COMMENT '是否是积分抵扣订单',
  `order_type` tinyint DEFAULT '1' COMMENT '订单类型：1普通订单，3积分订单，2拼团，5砍一砍 6 虚拟订单 7 付费商品订单 8 卡密订单 9预约到店 10 预约上门',
  `is_cycle_order` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否周期购订单：0-否，1-是',
  `is_card_order` tinyint NOT NULL DEFAULT '0' COMMENT '是否次卡订单：0-否，1-是',
  `is_presale` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否预售订单：0-否，1-是',
  `presale_type` tinyint unsigned DEFAULT NULL COMMENT '预售类型：1-全款预售，2-定金预售',
  `mark` tinyint DEFAULT '0' COMMENT '标记 12345',
  `vendor_id` int DEFAULT NULL COMMENT '供应商id',
  `cancel_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取消原因',
  `cash_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '现金金额',
  `cash_change_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '现金金额(找零)',
  `round_off_dime_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '抹角金额',
  `round_off_cents_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '抹分金额',
  `pos_user_id` int DEFAULT '0' COMMENT '后台管理员id',
  `device_code` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收银台支付时选择的打印设备码',
  `discount_change_price` decimal(10,2) DEFAULT NULL,
  `tax_rate` decimal(10,4) DEFAULT NULL COMMENT '税率(百分比)',
  `tax_rate_amount` decimal(10,2) DEFAULT NULL COMMENT '税率金额',
  `change_price_data` json DEFAULT NULL,
  `gift_card_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '礼品卡兑换金额',
  `delivery_date` date DEFAULT NULL COMMENT '计划配送日期（周期购子订单）',
  `delivery_time_slot` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '配送时间段（周期购子订单）',
  `period_index` tinyint unsigned DEFAULT NULL COMMENT '第几期（周期购子订单）',
  `time_index` tinyint unsigned DEFAULT NULL COMMENT '期内第几次（周期购子订单）',
  PRIMARY KEY (`order_id`) USING BTREE,
  UNIQUE KEY `order_sn` (`order_sn`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `order_status` (`order_status`) USING BTREE,
  KEY `shipping_status` (`shipping_status`) USING BTREE,
  KEY `pay_status` (`pay_status`) USING BTREE,
  KEY `shipping_id` (`logistics_id`) USING BTREE,
  KEY `store_id` (`shop_id`) USING BTREE,
