  KEY `referrer_user_id` (`referrer_user_id`) USING BTREE,
  KEY `is_need_commisson` (`is_need_commisson`) USING BTREE,
  KEY `idx_vendor_id` (`vendor_id`),
  KEY `idx_is_cycle_order` (`is_cycle_order`),
  KEY `idx_parent_order_id` (`parent_order_id`),
  KEY `idx_is_credit_order` (`is_credit_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单表';
