CREATE TABLE `order_item` (
  `item_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '订单商品信息自增id',
  `order_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '订单ID',
  `order_sn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `user_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品最终单价',
  `quantity` smallint unsigned NOT NULL DEFAULT '1' COMMENT '商品的购买数量',
  `product_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `product_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品的名称',
  `product_sn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品的唯一货号',
  `pic_thumb` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品缩略图',
  `sku_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '规格ID',
  `sku_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '【JSON】sku信息[{sku_id,sku_value,sku_name}]',
  `delivery_quantity` smallint unsigned NOT NULL DEFAULT '0' COMMENT '发货数量',
  `product_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '商品类型，1：实体，2：虚拟，3赠品',
  `is_gift` smallint unsigned NOT NULL DEFAULT '0' COMMENT '是否为赠品',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `is_pin` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否拼团',
  `prepay_price` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '预售价格',
  `commission` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '佣金数据',
  `origin_price` decimal(10,2) DEFAULT '0.00' COMMENT '商品初始价格',
  `promotion_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '优惠信息',
  `is_seckill` tinyint DEFAULT '0' COMMENT '是否秒杀',
  `extra_sku_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '附加属性',
  `suppliers_id` int unsigned NOT NULL DEFAULT '0' COMMENT '供应商id',
  `card_group_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡密商品组名称',
  `vendor_product_id` int DEFAULT NULL COMMENT '供应商产品表id',
  `vendor_product_sku_id` int DEFAULT NULL COMMENT '供应商产品sku表id',
  `vendor_id` int DEFAULT NULL COMMENT '供应商id',
  `vendor_product_supply_price` decimal(10,2) DEFAULT NULL COMMENT '供应商产品供货价',
  `change_price_data` json DEFAULT NULL COMMENT '改价data(涉及到的购物车的改价数据)',
  `admin_change_pre_price` decimal(10,2) DEFAULT NULL COMMENT '后台改价前价格',
  `gift_card_id` int DEFAULT '0' COMMENT '礼品卡兑换订单(礼品卡id)',
  `delivery_service_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '配送员服务费(单件快照，仅O2O写入)',
  `server_service_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '服务员服务费(单件快照，仅O2O上门服务订单写入)',
  `is_wholesale_line` tinyint NOT NULL DEFAULT '0' COMMENT 'B2B批发:1=批发行 0=零售行',
  `wholesale_grade_id` int NOT NULL DEFAULT '0' COMMENT 'B2B批发:等级快照(0=无)',
  `wholesale_base_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'B2B批发:批发基准价快照(冻结,审计/退款用,design §6)',
  PRIMARY KEY (`item_id`) USING BTREE,
  KEY `order_id` (`order_id`) USING BTREE,
  KEY `goods_id` (`product_id`) USING BTREE,
  KEY `idx_vendor_product_id` (`vendor_product_id`),
  KEY `idx_vendor_product_sku_id` (`vendor_product_sku_id`),
  KEY `idx_vendor_id` (`vendor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单的商品信息';
