DROP TABLE IF EXISTS `print`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `print` (
  `print_id` int NOT NULL AUTO_INCREMENT COMMENT '自增ID，打印机ID',
  `print_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '打印机名称',
  `print_sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '打印机SN',
  `print_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '打印机key',
  `third_account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第三方平台对接账号',
  `third_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第三方平台key',
  `print_number` int DEFAULT '0' COMMENT '打印联数',
  `platform` tinyint(1) DEFAULT '1' COMMENT '第三方平台 1=飞鹅云 2=商米云',
  `shop_id` int DEFAULT '0' COMMENT '店铺id',
  `status` tinyint DEFAULT '1' COMMENT '状态 1开启 2关闭',
  `add_time` int DEFAULT '0' COMMENT '打印机创建时间',
  `update_time` int DEFAULT '0' COMMENT '打印机修改时间',
  `delete_time` int DEFAULT '0' COMMENT '打印机删除时间',
  `auto_print` tinyint(1) DEFAULT '1' COMMENT '订单支付自动打印 1开启 2关闭',
  `voice_enabled` tinyint NOT NULL DEFAULT '1' COMMENT '语音播报开关：1=开启，2=关闭',
  `voice_content_type` tinyint NOT NULL DEFAULT '0' COMMENT '语音播报内容：0=订单号+金额，1=仅金额',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '店铺默认打印机 1是0否',
  PRIMARY KEY (`print_id`) USING BTREE,
  KEY `print_sn` (`print_sn`),
  KEY `shop_id` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='打印机表';
/*!40101 SET character_set_client = @saved_cs_client */;

