CREATE TABLE `print_config` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `print_id` int NOT NULL COMMENT '打印机ID',
  `template` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '打印模版JSON',
  `type` tinyint(1) DEFAULT '1' COMMENT '类型 1购物小票 ',
  `paper_size` tinyint NOT NULL DEFAULT '58' COMMENT '纸张尺寸（毫米）：58=58mm，80=80mm。历史数据默认 58mm',
  `add_time` int DEFAULT '0' COMMENT '创建时间',
  `update_time` int DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `print_id` (`print_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='打印机配置表';
