/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_attributes` (
  `attributes_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID号 ',
  `product_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '取值于goods的goods_id ',
  `attr_type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '属性类型，0:普通属性，1：规格属性，2：附加规格',
  `attr_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '属性所属类型的名称',
  `attr_value` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '具体属性的值 ',
  `attr_price` decimal(8,2) unsigned DEFAULT '0.00' COMMENT '属性价格 ',
  `attr_color` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '属性颜色',
  `attr_pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '属性图片',
  `attr_pic_thumb` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '属性缩略图',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`attributes_id`) USING BTREE,
  KEY `goods_id` (`product_id`) USING BTREE,
  KEY `attr_type` (`attr_type`) USING BTREE,
  KEY `attr_name` (`attr_name`) USING BTREE,
  KEY `attr_value` (`attr_value`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5234 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品属性表';
