  `shop_id` int NOT NULL DEFAULT '0' COMMENT '门店ID：0-平台商品，>0-门店商品',
  `operation_type` tinyint(1) NOT NULL COMMENT '操作类型：0-下架，1-上架',
  `scheduled_time` bigint NOT NULL COMMENT '计划执行时间（时间戳）',
  `execute_time` bigint DEFAULT NULL COMMENT '实际执行时间（时间戳）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '执行状态：0-待执行，1-执行成功，2-执行失败',
  `error_message` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '失败原因',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '重试次数',
  `create_time` bigint NOT NULL COMMENT '创建时间',
  `update_time` bigint NOT NULL COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_shop_id` (`shop_id`),
  KEY `idx_scheduled_time` (`scheduled_time`),
  KEY `idx_status` (`status`),
  KEY `idx_operation_type` (`operation_type`),
  KEY `idx_product_shop` (`product_id`,`shop_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='商品自动上下架表';
/*!40101 SET character_set_client = @saved_cs_client */;

