DROP TABLE IF EXISTS `product_package`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_package` (
  `package_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '组合套餐id',
  `package_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '促销活动的名称 ',
  `package_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '促销活动的描述',
  `package_type` tinyint unsigned NOT NULL COMMENT '4,组合优惠',
  `product_id` mediumint unsigned NOT NULL COMMENT '参加活动的id，取值于goods的goods_id ',
  `start_time` int unsigned NOT NULL COMMENT '活动开始时间 ',
  `end_time` int unsigned NOT NULL COMMENT '活动结束时间 ',
  `is_finished` tinyint unsigned NOT NULL COMMENT '活动是否结束，0，结束；1，未结束',
  `ext_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `store_id` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`package_id`) USING BTREE,
  KEY `act_name` (`package_name`,`package_type`,`product_id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拍卖活动和夺宝奇兵活动配置信息';
