DROP TABLE IF EXISTS `product_promotion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_promotion` (
  `promotion_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '活动id',
  `promotion_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动名称',
  `start_time` int unsigned NOT NULL DEFAULT '0' COMMENT '开始时间',
  `end_time` int unsigned NOT NULL DEFAULT '0' COMMENT '结束时间',
  `limit_user_rank` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '[JSON]仅限会员等级',
  `range` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '活动范围:0,全部商品;3,指定商品.4，不含以下商品',
  `range_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '[json]活动范围相关信息',
  `min_order_amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '订单金额下限',
  `max_order_amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '订单金额上限，可用于阶梯设置',
  `promotion_type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '优惠类型，1：满减，2：折扣，3：满赠',
  `promotion_type_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '[data]类型相关数据，如满减金额、折扣金额、赠品等',
  `is_available` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否启用',
  `sort_order` tinyint unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `rules_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '优惠规则：1 阶梯优惠 0 循环优惠',
  `unit` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '优惠单位：1 元 2 件',
  PRIMARY KEY (`promotion_id`) USING BTREE,
  KEY `act_name` (`promotion_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品促销';
/*!40101 SET character_set_client = @saved_cs_client */;

