DROP TABLE IF EXISTS `product_sku`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_sku` (
  `sku_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '规格id',
  `product_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '商品id',
  `sku_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品规格值',
  `sku_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '商品规格值（json）',
  `sku_sn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '货品编码',
  `sku_stock` int unsigned DEFAULT '0' COMMENT '货品库存',
  `sku_tsn` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '条形码',
  `sku_price` decimal(8,2) unsigned DEFAULT '0.00' COMMENT '货品价格',
  `is_enabled` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否启用：0-禁用，1-启用',
  `market_price` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '市场售价 ',
  `cost_price` decimal(10,2) DEFAULT '0.00' COMMENT '成本价',
  `delivery_service_fee_type` tinyint NOT NULL DEFAULT '0' COMMENT '配送员服务费类型：0=固定金额 1=按比例',
  `delivery_service_fee_value` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '配送员服务费值：固定金额(元)或按比例(%)',
  `server_service_fee_type` tinyint NOT NULL DEFAULT '0' COMMENT '服务员服务费类型：0=固定金额 1=按比例',
  `server_service_fee_value` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '服务员服务费值：固定金额(元)或按比例(%)',
  `vendor_product_sku_id` int DEFAULT NULL COMMENT '供应商商品规格 ID',
  PRIMARY KEY (`sku_id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=750 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品属性';
/*!40101 SET character_set_client = @saved_cs_client */;

