  `operation_type` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作描述',
  `add_time` bigint DEFAULT NULL COMMENT '操作时间',
  `review_rejected_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '审核驳回原因',
  `add_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作人',
  PRIMARY KEY (`allocate_operation_id`)
