  `promotion_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '活动id',
  `promotion_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动名称',
  `start_time` int unsigned NOT NULL DEFAULT '0' COMMENT '开始时间',
  `end_time` int unsigned NOT NULL DEFAULT '0' COMMENT '结束时间',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型1秒杀2优惠券3满减4折扣5满赠6限时折扣',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `relation_id` int DEFAULT '0' COMMENT '活动对应的id',
  `range` tinyint DEFAULT '0' COMMENT '活动范围:0,全部商品;3,指定商品.4，不含以下商品',
  `range_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '[json]活动范围相关信息',
  `sku_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '允许的sku',
  `is_available` tinyint DEFAULT '1' COMMENT '是否启用',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '是否删除',
  `member_range` tinyint(1) NOT NULL DEFAULT '0' COMMENT '适用会员范围：0-全部会员，1-指定标记的会员',
  `member_marks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '选择的会员标记列表（JSON格式，如[1,2,3]）',
  `member_scope` json DEFAULT NULL COMMENT '会员标签二期人群圈选(MemberAudienceDTO序列化JSON)，非空则优先于 member_range/member_marks',
  PRIMARY KEY (`promotion_id`) USING BTREE,
  KEY `start_time` (`start_time`) USING BTREE,
  KEY `end_time` (`end_time`) USING BTREE,
  KEY `shop_id` (`shop_id`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `relation_id` (`relation_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='活动表';
/*!40101 SET character_set_client = @saved_cs_client */;

