DROP TABLE IF EXISTS `purchase_operation_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchase_operation_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `business_type` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `business_id` bigint NOT NULL,
  `action` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `from_status` tinyint DEFAULT NULL,
  `to_status` tinyint DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_time` bigint NOT NULL DEFAULT '0',
  `create_by_id` bigint NOT NULL DEFAULT '0',
  `create_by_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `update_time` bigint NOT NULL DEFAULT '0',
  `update_by_id` bigint NOT NULL DEFAULT '0',
  `update_by_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `is_del` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_purchase_operation_log_business` (`business_type`,`business_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='采购业务操作日志';
