DROP TABLE IF EXISTS `purchase_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchase_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '采购订单号',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '单据类型：1采购订单，2采购入库单',
  `voucher_url` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '入库凭证图片地址，仅采购入库单使用',
  `shop_id` int NOT NULL COMMENT '组织ID，0为平台自营',
  `vendor_id` int NOT NULL,
  `vendor_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称快照',
  `vendor_code` varchar(80) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商编码快照',
  `vendor_contact` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商主联系方式快照',
  `vendor_account_snapshot` text COLLATE utf8mb4_general_ci COMMENT '银行账户快照JSON',
  `status` tinyint NOT NULL COMMENT '1待入库，2部分入库，3已完成，4已关闭',
  `expected_delivery_date` bigint NOT NULL COMMENT '预计送达日期',
  `shipping_method` tinyint NOT NULL COMMENT '1物流，2无需物流',
  `logistics_id` int DEFAULT NULL,
  `logistics_name` varchar(120) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tracking_no` varchar(120) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `finish_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `product_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `ordered_quantity` int NOT NULL DEFAULT '0',
  `received_quantity` int NOT NULL DEFAULT '0',
  `finish_time` bigint DEFAULT NULL,
  `finish_by_id` bigint DEFAULT NULL,
  `finish_by_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `create_time` bigint NOT NULL DEFAULT '0',
  `create_by_id` bigint NOT NULL DEFAULT '0',
  `create_by_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `update_time` bigint NOT NULL DEFAULT '0',
  `update_by_id` bigint NOT NULL DEFAULT '0',
  `update_by_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `is_del` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_purchase_order_sn` (`order_sn`),
  KEY `idx_purchase_order_shop_status` (`shop_id`,`status`,`expected_delivery_date`),
  KEY `idx_purchase_order_shop_type_status` (`shop_id`,`type`,`status`,`create_time`),
  KEY `idx_purchase_order_vendor_date` (`shop_id`,`vendor_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='采购订单';
/*!40101 SET character_set_client = @saved_cs_client */;

