DROP TABLE IF EXISTS `region`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `region` (
  `region_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `level` tinyint unsigned DEFAULT '0' COMMENT '层级',
  `region_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '地区的名字',
  `parent_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '该地区的上一个节点的地区id',
  `is_hot` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否热门',
  `sort_order` int NOT NULL DEFAULT '50' COMMENT '排序值，数值越小越靠前',
  `first_word` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '首字母',
  `standard_code` varchar(8) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '国家或地区稳定标准代码',
  PRIMARY KEY (`region_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE,
  KEY `level` (`level`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=820213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='地区列表';
/*!40101 SET character_set_client = @saved_cs_client */;

