DROP TABLE IF EXISTS `request_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `request_log` (
  `request_log_id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '地址',
  `http_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '请求类型',
  `class_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类名 + 方法名',
  `request_params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '请求参数',
  `add_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '操作时间',
  `admin_username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '后台用户名称',
  `admin_id` int DEFAULT NULL COMMENT '后台用户id',
  `admin_ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'ip地址',
  `platform` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '平台信息',
  PRIMARY KEY (`request_log_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `request_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `request_log` ENABLE KEYS */;
DROP TABLE IF EXISTS `reservation_tpl`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reservation_tpl` (
  `reservation_tpl_id` int NOT NULL AUTO_INCREMENT COMMENT '预约模板ID',
  `template_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板名称',
  `reservation_type` tinyint NOT NULL COMMENT '预约时间类型：0=无需提前,1=需提前N天,2=根据下单时间配置',
  `advance_number` int DEFAULT '0' COMMENT '需提前预约的天数，仅当reservation_type=1时有效',
  `advance_unit` varchar(1) COLLATE utf8mb4_general_ci DEFAULT 'd' COMMENT '需提前预约的时间单位：d=天,h=小时，仅当reservation_type=1时有效',
  `max_days` int NOT NULL COMMENT '最长允许预约天数',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认，1表示默认',
  PRIMARY KEY (`reservation_tpl_id`),
  KEY `idx_shop_id` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='产品预约配置';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `reservation_tpl` DISABLE KEYS */;
/*!40000 ALTER TABLE `reservation_tpl` ENABLE KEYS */;
DROP TABLE IF EXISTS `salesman`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salesman` (
  `salesman_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL COMMENT '用户id',
  `level` int DEFAULT '1' COMMENT '等级',
  `group_id` int DEFAULT '0' COMMENT '分组id',
  `pid` int NOT NULL DEFAULT '0' COMMENT '上级分销员',
  `add_time` int DEFAULT NULL,
  `shop_id` int DEFAULT NULL COMMENT '所属店铺',
  `sale_amount` decimal(10,2) DEFAULT '0.00' COMMENT '累计销售额',
  PRIMARY KEY (`salesman_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分销员';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `salesman` DISABLE KEYS */;
/*!40000 ALTER TABLE `salesman` ENABLE KEYS */;
DROP TABLE IF EXISTS `salesman_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salesman_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `shop_id` int DEFAULT NULL COMMENT '店铺ID',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `salesman_config` DISABLE KEYS */;
INSERT INTO `salesman_config` VALUES (2,0,'salesmanConfig','{\"code\":\"salesmanConfig\",\"level\":[{\"condition\":{\"inviteSales\":{\"checked\":false,\"value\":\"2\"},\"salesAmount\":{\"checked\":false,\"value\":\"2\"},\"salesInviteUsers\":{\"checked\":false,\"value\":\"2\"},\"selfBuyAmount\":{\"checked\":false,\"value\":\"2\"}},\"downSalesmanRate\":\"1\",\"id\":1,\"name\":\"普通分销员\",\"rate\":\"1\"},{\"condition\":{\"salesAmount\":{\"checked\":false,\"title\":\"推广金额\",\"unit\":\"元\",\"value\":\"20\"},\"salesInviteUsers\":{\"checked\":true,\"title\":\"发展客户数\",\"unit\":\"人\",\"value\":\"5\"},\"selfBuyAmount\":{\"checked\":false,\"title\":\"自购金额\",\"unit\":\"元\",\"value\":\"10\"}},\"downSalesmanRate\":\"3\",\"id\":2,\"name\":\"精品分销员\",\"rate\":\"2\"},{\"condition\":{\"salesAmount\":{\"checked\":true,\"disabled\":false,\"title\":\"推广金额\",\"unit\":\"元\",\"value\":\"21\"},\"salesInviteUsers\":{\"checked\":true,\"disabled\":true,\"title\":\"发展客户数\",\"unit\":\"人\",\"value\":\"7\"},\"selfBuyAmount\":{\"checked\":true,\"disabled\":false,\"title\":\"自购金额\",\"unit\":\"元\",\"value\":\"21\"}},\"downSalesmanRate\":\"4\",\"id\":3,\"name\":\"稀有分销员\",\"rate\":\"3\"}],\"saleType\":1}'),(3,0,'salesmanSettlement','{\"dateType\":0,\"desc\":\"\",\"registerToSalesman\":0,\"settlementType\":2}');
/*!40000 ALTER TABLE `salesman_config` ENABLE KEYS */;
DROP TABLE IF EXISTS `salesman_content`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salesman_content` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面图片',
  `start_time` int unsigned NOT NULL DEFAULT '0' COMMENT '推送时间',
  `end_time` int unsigned DEFAULT '0' COMMENT '失效时间',
  `describe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '页面描述',
  `is_top` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否置顶：1 是 0 否',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '正文内容',
