DROP TABLE IF EXISTS `service_staff`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_staff` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `nickname` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '昵称',
  `avatar` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '头像',
  `phone` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '联系电话',
  `member_id` int DEFAULT NULL COMMENT '关联会员用户ID',
  `store_id` int NOT NULL COMMENT '所属门店ID',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '类型：1-配送员，2-服务员',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '账号状态：0-禁用，1-启用',
  `work_status` tinyint NOT NULL DEFAULT '0' COMMENT '工作状态：0-已下班，1-空闲中，2-配送中/服务中',
  `completed_order_count` int NOT NULL DEFAULT '0' COMMENT '已完成订单数',
  `completed_order_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '已完成订单金额',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `is_delete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除：0-否，1-是',
  PRIMARY KEY (`id`),
  KEY `idx_store_id` (`store_id`),
  KEY `idx_member_id` (`member_id`),
  KEY `idx_type` (`type`),
  KEY `idx_status` (`status`),
  KEY `idx_work_status` (`work_status`),
  KEY `idx_store_phone` (`store_id`,`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='服务人员表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `service_staff` DISABLE KEYS */;
/*!40000 ALTER TABLE `service_staff` ENABLE KEYS */;
DROP TABLE IF EXISTS `service_staff_wallet`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_staff_wallet` (
  `wallet_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '钱包ID',
  `staff_id` int NOT NULL COMMENT '关联 service_staff.staff_id',
  `balance` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '可用余额',
  `frozen_balance` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '冻结余额',
  `total_income` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '累计收入',
  `create_time` bigint DEFAULT NULL COMMENT '创建时间',
  `update_time` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`wallet_id`),
  UNIQUE KEY `uk_staff_id` (`staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='O2O配送员/服务员钱包';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `service_staff_wallet` DISABLE KEYS */;
/*!40000 ALTER TABLE `service_staff_wallet` ENABLE KEYS */;
DROP TABLE IF EXISTS `service_staff_wallet_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_staff_wallet_log` (
  `log_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '流水ID',
  `staff_id` int NOT NULL COMMENT '配送员/服务员ID',
  `order_id` int DEFAULT NULL COMMENT '关联订单ID(周期购为子订单ID)',
  `withdraw_id` int DEFAULT NULL COMMENT '关联提现单ID',
  `transaction_sn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '交易编号：订单编号或提现编号',
  `amount` decimal(10,2) NOT NULL COMMENT '变动金额：正=入账 负=扣减',
  `balance_after` decimal(12,2) NOT NULL COMMENT '变动后余额',
  `frozen_after` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '变动后冻结余额',
  `business_type` tinyint NOT NULL DEFAULT '1' COMMENT '业务来源：1=配送服务费 2=服务员服务费',
  `type` tinyint NOT NULL COMMENT '类型：1=服务费入账 2=提现完成(实扣冻结) 3=扣减 4=提现申请(余额→冻结) 5=提现驳回(冻结→回退余额)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` bigint DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`log_id`),
  KEY `idx_staff_id` (`staff_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_withdraw_id` (`withdraw_id`),
  KEY `idx_staff_business_type` (`staff_id`,`business_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='O2O配送员/服务员钱包流水';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `service_staff_wallet_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `service_staff_wallet_log` ENABLE KEYS */;
DROP TABLE IF EXISTS `service_staff_withdraw`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_staff_withdraw` (
  `withdraw_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '提现单ID',
  `withdraw_sn` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易编号（业务唯一）',
  `staff_id` int NOT NULL COMMENT '配送员/服务员ID',
  `business_type` tinyint NOT NULL DEFAULT '1' COMMENT '业务来源：1=配送服务费 2=服务员服务费',
  `amount` decimal(10,2) NOT NULL COMMENT '申请提现金额',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0=待审核 1=已打款 2=已驳回',
  `account_id` int NOT NULL COMMENT '关联 user_withdraw_account.account_id',
  `account_type` tinyint NOT NULL COMMENT '冗余：1银行卡 2支付宝 3微信',
  `account_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '冗余收款人姓名',
  `account_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '冗余收款账号',
  `bank_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '冗余开户行',
  `admin_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '管理员备注',
  `payment_voucher` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '打款凭证图片URL',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '拒绝理由',
  `audit_admin_id` int DEFAULT '0' COMMENT '审核管理员ID',
  `audit_time` bigint DEFAULT NULL COMMENT '审核时间',
  `apply_time` bigint NOT NULL COMMENT '申请时间',
  `frequency_unit` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'day' COMMENT '快照：申请时的频次单位 day/week/month',
  `period_start` bigint NOT NULL COMMENT '快照：所属计数周期起（含）',
  `period_end` bigint NOT NULL COMMENT '快照：所属计数周期止（不含）',
  `create_time` bigint DEFAULT NULL COMMENT '创建时间',
  `update_time` bigint DEFAULT NULL COMMENT '更新时间',
  `is_delete` tinyint NOT NULL DEFAULT '0' COMMENT '0=有效 1=删除',
  PRIMARY KEY (`withdraw_id`),
  UNIQUE KEY `uk_withdraw_sn` (`withdraw_sn`),
  KEY `idx_staff_business_period` (`staff_id`,`business_type`,`period_start`,`is_delete`),
  KEY `idx_status_apply_time` (`status`,`apply_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='配送员/服务员提现申请';
