CREATE TABLE `shipping_type` (
  `shipping_type_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '配送类型id',
  `shipping_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `shipping_default_id` int unsigned NOT NULL DEFAULT '0' COMMENT '默认发货物流公司ID',
  `shipping_type_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '描述',
  `shipping_time_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货时间描述',
  `is_support_cod` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否支持货到付款',
  `sort_order` smallint unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  PRIMARY KEY (`shipping_type_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='配送类型';
