DROP TABLE IF EXISTS `shop`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shop` (
  `shop_id` int NOT NULL COMMENT '店铺id(随机分配)',
  `shop_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '店铺名称',
  `add_time` int DEFAULT '0' COMMENT '店铺创建时间',
  `shop_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '店铺logo',
  `click_count` int DEFAULT '0' COMMENT '点击量',
  `status` tinyint DEFAULT '1' COMMENT '店铺状态1开业  4暂停运营 10关店  ',
  `merchant_id` int unsigned DEFAULT '0' COMMENT '商户id',
  `shop_money` decimal(10,2) DEFAULT '0.00' COMMENT '店铺资金',
  `frozen_money` decimal(10,2) DEFAULT '0.00' COMMENT '冻结资金',
  `contact_mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '联系电话',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '简介',
  `kefu_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '客服电话',
  `kefu_weixin` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '客服微信',
  `kefu_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '客服链接',
  `is_contact_kefu` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否联系客服：1 是 0 否',
  `kefu_inlet` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '[json]客服入口信息页面： 1 商品详情页 2 订单页',
  `ship_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '发货信息',
  `receive_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '收货信息',
  `last_login_time` int unsigned NOT NULL DEFAULT '0' COMMENT '最后登录时间',
  `vendor_set_price_type` tinyint DEFAULT '3' COMMENT '供应商设价方式(1按比例，2-按固定数值加价，3-默认售价)',
  `vendor_set_price_auto_value` decimal(10,2) DEFAULT NULL COMMENT '智能设价（百分比或固定数值）',
  `service_fee_rate` decimal(10,2) DEFAULT NULL COMMENT '服务费比例',
  `fee_rate` decimal(10,2) DEFAULT NULL COMMENT '手续费比例',
  `shop_type` tinyint DEFAULT '1' COMMENT '1店铺，2门店，3自提点',
  `store_parent_id` int unsigned DEFAULT NULL COMMENT '店铺父级id',
  `shop_cover_picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '门店封面',
  `shop_show_picture` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '门店相册',
  `shop_contact_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '联系方式',
  `shop_open_close_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '运营时间',
  `shop_region_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'region表id',
  `shop_detailed_address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '门店详细地址',
  `shop_longitude` decimal(10,6) DEFAULT NULL COMMENT '店铺经度',
  `shop_latitude` decimal(10,6) DEFAULT NULL COMMENT '店铺纬度',
  `shop_star` decimal(10,6) DEFAULT '0.000000' COMMENT '评星',
  `shop_total_star` int DEFAULT '0' COMMENT '总评价分数',
  `shop_star_num` int DEFAULT '0' COMMENT '评价数量',
  `shop_sales` int DEFAULT '0' COMMENT '销量',
  `use_shop_category` int(10) unsigned zerofill DEFAULT '0000000000' COMMENT '是否使用门店分类',
  `shop_show_category` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '店铺选择展示分类',
  `auto_erase_zero` tinyint NOT NULL DEFAULT '0' COMMENT '店内收银自动抹零：0关闭 1开启',
  `auto_deduction_points` tinyint NOT NULL DEFAULT '0' COMMENT '收银积分基于订单自动抵扣：0关闭 1开启',
  `default_collection_method` tinyint NOT NULL DEFAULT '1' COMMENT '收银机默认收款方式：(默认)1-现金支付 2-扫码支付 3-余额支付 4-积分支付',
  `auto_add_cart_after_scan` tinyint(1) NOT NULL DEFAULT '1' COMMENT '扫码后自动加入购物车：0关闭 1开启',
  `auto_print_online_order` tinyint NOT NULL DEFAULT '1' COMMENT '线上订单自动打印：0关闭 1开启',
  `auto_print_offline_order` tinyint NOT NULL DEFAULT '1' COMMENT '线下订单自动打印：0关闭 1开启',
  `shop_common_remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '店铺常用备注列表(JSON数组)',
  `pos_product_source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收银台商品来源(JSON数组)：0-全部商品，1-门店自建商品，2-平台分配商品，3-供应商商品',
  `is_delete` tinyint DEFAULT NULL COMMENT '是否删除  null或者0标识未删除  1 表示已删除',
  PRIMARY KEY (`shop_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺表';
/*!40101 SET character_set_client = @saved_cs_client */;

