CREATE TABLE `shop_account_log` (
  `shop_account_log_id` int unsigned NOT NULL AUTO_INCREMENT,
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '添加时间',
  `shop_money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '店铺资金',
  `frozen_money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '店铺冻结资金',
  `type` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '1，提现',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '备注',
  `new_shop_money` decimal(10,2) DEFAULT '0.00' COMMENT '变动后余额；线上历史余额未知时为空',
  `new_frozen_money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '现店铺冻结资金',
