  `balance_type` tinyint NOT NULL DEFAULT '1' COMMENT '资金账户：1线下，2线上',
  `pay_channel` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '线上渠道WECHAT/HUIFU/ALIPAY',
  `change_amount` decimal(12,2) DEFAULT NULL COMMENT '资金变动额，历史空值按旧日志规则计算',
  `event_key` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '资金事件唯一键，防止重复记账',
  PRIMARY KEY (`shop_account_log_id`) USING BTREE,
