CREATE TABLE `shop_deposit` (
  `shop_deposit_id` int unsigned NOT NULL AUTO_INCREMENT,
  `owner_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '持有者类型 1店铺 2供应商',
  `owner_id` int unsigned NOT NULL DEFAULT '0' COMMENT '持有者id(店铺为shopId,供应商为vendorId)',
  `paid` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '实缴余额(净额)=充值入账-提现-退还-平台扣除',
  `required_manual` decimal(10,2) unsigned DEFAULT NULL COMMENT '手动应缴覆盖值,NULL=按规则实时算',
