  `supplement_due_time` int unsigned NOT NULL DEFAULT '0' COMMENT '补缴缓冲到期时间,0未触发',
  `collect_activated` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '收取是否已激活:0未激活(首单前) 1已激活;节点=上架收在上架激活,节点=首单收在首单激活',
  `penalty_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '惩罚状态 0正常 1限制上架 2全店下架(DepositPenaltyAction)',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '账户状态 1正常',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `required_snapshot` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '上次应缴快照(类目变更diff用,记录调整前后值)',
  PRIMARY KEY (`shop_deposit_id`) USING BTREE,
  UNIQUE KEY `uk_owner` (`owner_type`,`owner_id`) USING BTREE
