CREATE TABLE `shop_meituan_delivery_config` (
  `shop_meituan_delivery_config_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '门店ID',
  `enabled` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否开启美团配送 0关闭 1开启',
  `mt_shop_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '美团门店ID（本系统生成，注册到美团的 shop_id）',
  `mt_shop_status` tinyint NOT NULL DEFAULT '0' COMMENT '美团门店状态 0未注册 10创建审核驳回 20创建审核通过 30创建成功 40上线可发单 50修改审核驳回 60修改审核通过',
  `goods_category` int DEFAULT NULL COMMENT '门店经营一级品类（美团 category 代码，如 110）',
  `second_category` int DEFAULT NULL COMMENT '门店经营二级品类（美团 second_category 代码，如 110002）',
  `delivery_service_codes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '可用配送服务代码，逗号分隔（飞速达4002/快速达4011/及时达4012/集中送4013 等）',
  `pay_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '支付方式 1账期支付 2余额支付',
  `trigger_mode` tinyint(1) NOT NULL DEFAULT '1' COMMENT '触发模式 1手动呼叫 2付款后自动呼叫',
  `shop_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '美团门店名称（默认取 shop.shop_title，可覆盖）',
  `contact_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `city_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '城市名称',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '门店详细地址（默认取 shop.shop_detailed_address，可覆盖）',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '门店经度',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '门店纬度',
  `business_hours` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '营业时间（文本或 JSON）',
  `enterprise_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '企业全称',
  `enterprise_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '企业地址',
  `business_license_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '营业执照编号',
  `license_long_term` tinyint(1) NOT NULL DEFAULT '0' COMMENT '营业执照是否长期有效 0否 1是',
  `license_valid_from` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '营业执照有效期开始（yyyy-MM-dd）',
  `license_valid_to` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '营业执照有效期截止（long_term=1 时可空）',
  `establish_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '注册/成立日期',
  `license_authority` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发证登记机关',
  `license_approval_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '核准日期',
  `business_scope` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '经营范围',
  `legal_person_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '法人/经营者姓名',
  `legal_person_id_card` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '法人/经营者身份证号',
  `legal_person_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '法人/经营者手机号',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '美团审核备注 / 驳回原因',
  `add_time` int unsigned NOT NULL DEFAULT '0' COMMENT '添加时间',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`shop_meituan_delivery_config_id`) USING BTREE,
  UNIQUE KEY `uk_shop_id` (`shop_id`) USING BTREE,
  KEY `idx_mt_shop_id` (`mt_shop_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='门店美团配送配置';
