DROP TABLE IF EXISTS `shop_withdraw`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shop_withdraw` (
  `shop_withdraw_log_id` int NOT NULL AUTO_INCREMENT,
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属店铺',
  `amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '提现金额',
  `handling_fee` decimal(10,2) DEFAULT NULL COMMENT '手续费',
  `handling_rate` decimal(10,2) DEFAULT NULL COMMENT '手续费率',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态0待审核2审核不通过3完成4待打款',
  `add_time` int unsigned NOT NULL COMMENT '提现时间',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提现备注',
  `merchant_account_id` int DEFAULT NULL COMMENT '提现到',
  `account_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '提现时账户信息数据',
  `audit_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核备注',
  `payment_voucher` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '打款凭证',
  `withdraw_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '提现单号',
  `withdraw_type` tinyint NOT NULL DEFAULT '1' COMMENT '提现方式:1线下 2线上(微信API)',
  `channel_withdraw_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信提现单号',
  `channel_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信侧状态',
  `pay_channel` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'WECHAT' COMMENT '线上提现渠道：WECHAT-微信，HUIFU-汇付，ALIPAY-支付宝',
  `offline_frozen_amount` decimal(12,2) DEFAULT NULL COMMENT '本申请冻结的线下金额，新线上为0，历史NULL待核账',
  `channel_sub_mch_id` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请时渠道子商户号快照，避免绑定变更影响出金和查单',
  PRIMARY KEY (`shop_withdraw_log_id`) USING BTREE,
  UNIQUE KEY `uk_withdraw_sn` (`withdraw_sn`),
  KEY `idx_shop_channel_status` (`shop_id`,`pay_channel`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺提现记录';
