/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `user_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '会员资料自增id ',
  `username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `mobile_validated` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '手机号是否已验证',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员邮箱',
  `email_validated` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '邮箱是否已验证',
  `nickname` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '昵称',
  `password` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户密码',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '用户现有余额',
  `frozen_balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '用户冻结余额',
  `commission_balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '分销佣金可提现余额（上线后新结算佣金累加，老数据归余额）',
  `frozen_commission_balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '分销佣金提现冻结余额',
  `points` int unsigned NOT NULL DEFAULT '0' COMMENT '积分',
  `growth_points` int unsigned NOT NULL DEFAULT '0' COMMENT '成长值',
  `address_id` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '当前会员地址',
  `reg_time` int unsigned NOT NULL DEFAULT '0' COMMENT '注册时间',
  `last_login` int unsigned NOT NULL DEFAULT '0' COMMENT '最后一次登录时间',
  `last_ip` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最后一次登录IP',
  `rank_id` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '会员等级id',
  `referrer_user_id` mediumint NOT NULL DEFAULT '0' COMMENT '推荐人会员id',
  `from_tag` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '公众号1,小程序2,H5,PC4,APP5',
  `is_svip` tinyint(1) DEFAULT '0' COMMENT '是否是超级会员 1是 0不是 2过期',
  `svip_expire_time` int DEFAULT '0' COMMENT '会员过期时间',
  `order_count` mediumint NOT NULL DEFAULT '0' COMMENT '累积消费次数',
  `order_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '累积消费金额',
  `history_product_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '【JSON】历史浏览记录id：number[]',
  `is_distribution` tinyint(1) DEFAULT '0' COMMENT '是否是分销员（已弃用）',
  `distribution_register_time` int DEFAULT '0' COMMENT '分销员注册时间（已弃用）',
  `wechat_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信二维码图片',
  `is_company_auth` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否企业认证：1 是 0 否',
  `status` tinyint DEFAULT '1' COMMENT '状态；0-禁用，1-启用',
  `user_type` tinyint DEFAULT '0' COMMENT '0会员，1游客',
  `admin_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员标签',
  `mark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '标记12345',
  PRIMARY KEY (`user_id`) USING BTREE,
  UNIQUE KEY `username` (`username`) USING BTREE,
  KEY `email` (`email`) USING BTREE,
  KEY `parent_id` (`referrer_user_id`) USING BTREE,
  KEY `is_distribution` (`is_distribution`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户表';
