  `new_balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '操作后的余额数据',
  `new_frozen_balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '操作后的冻结的余额',
