/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor` (
  `vendor_id` int NOT NULL AUTO_INCREMENT COMMENT '自增ID，供应商ID',
  `source_type` tinyint NOT NULL DEFAULT '1' COMMENT '来源类型：1入驻供应商，2自建供应商',
  `shop_id` int NOT NULL DEFAULT '0' COMMENT '自建供应商所属组织',
  `vendor_code` varchar(80) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '自建供应商编码',
  `purchase_category_id` bigint DEFAULT NULL COMMENT '采购供应商分类ID',
  `vendor_logo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '供应商logo',
  `add_time` int DEFAULT '0' COMMENT '供应商创建时间',
  `contact_mobile` varchar(32) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '联系电话',
  `vendor_data` text COLLATE utf8mb4_general_ci COMMENT '供应商信息JSON',
  `person_data` text COLLATE utf8mb4_general_ci COMMENT '个人信息JSON',
  `status` tinyint DEFAULT '1' COMMENT '状态 1开启 2关闭',
  `after_sales_review` tinyint DEFAULT '0' COMMENT '售后审核 0关闭 1开启',
  `type` tinyint(1) DEFAULT '1' COMMENT '类型 1个人 2企业',
  `vendor_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '供应商名称',
  `kefu_phone` varchar(32) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '客服电话',
  `ship_info` text COLLATE utf8mb4_general_ci COMMENT '发货信息JSON',
  `receive_info` text COLLATE utf8mb4_general_ci COMMENT '收货信息JSON',
  `vendor_money` decimal(10,2) DEFAULT '0.00' COMMENT '供应商资金',
  `frozen_money` decimal(10,2) DEFAULT '0.00' COMMENT '冻结资金',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '简介',
  `last_login_time` int unsigned NOT NULL DEFAULT '0' COMMENT '最后登录时间',
  `service_fee_rate` decimal(10,2) DEFAULT NULL COMMENT '服务费比例',
  `fee_rate` decimal(10,2) DEFAULT NULL COMMENT '手续费比例',
  `self_vendor_name_key` varchar(320) COLLATE utf8mb4_general_ci GENERATED ALWAYS AS ((case when (`source_type` = 2) then concat(`shop_id`,_utf8mb4':',trim(`vendor_name`)) else NULL end)) STORED,
  `self_vendor_code_key` varchar(160) COLLATE utf8mb4_general_ci GENERATED ALWAYS AS ((case when ((`source_type` = 2) and (`vendor_code` is not null) and (trim(`vendor_code`) <> _utf8mb4'')) then concat(`shop_id`,_utf8mb4':',trim(`vendor_code`)) else NULL end)) STORED,
  PRIMARY KEY (`vendor_id`) USING BTREE,
  UNIQUE KEY `uk_vendor_self_name` (`self_vendor_name_key`),
  UNIQUE KEY `uk_vendor_self_code` (`self_vendor_code_key`),
  KEY `idx_vendor_source_shop_status` (`source_type`,`shop_id`,`status`),
  KEY `idx_vendor_purchase_category` (`purchase_category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商表';
/*!40101 SET character_set_client = @saved_cs_client */;

