DROP TABLE IF EXISTS `vendor_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor_product` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `product_name` varchar(768) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `product_brand_id` int DEFAULT NULL COMMENT '商品品牌ID',
  `product_category_id` int NOT NULL COMMENT '商品类目ID',
  `product_sn_generate_type` tinyint NOT NULL COMMENT '商品编码生成类型；1-系统生成，2-手动输入',
  `product_brief` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品描述',
  `product_state` tinyint NOT NULL COMMENT '商品状态；0-断供，1-在售',
  `sku_type` tinyint NOT NULL COMMENT '规格类型，1-单规格，2-多规格',
  `product_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '商品详情',
  `audit_state` tinyint NOT NULL COMMENT '商品审核状态；0-待审核，1-审核通过，2-审核失败',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品实际图片',
  `pic_thumb` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品缩略图片',
  `pic_original` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品原始图片',
  `pic_large` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '高清图片url',
  `is_recycle` tinyint NOT NULL COMMENT '是否回收；0-否，1-是',
  `vendor_id` int NOT NULL COMMENT '供应商 ID',
  `source_product_id` int DEFAULT NULL COMMENT '来源店铺/门店商品ID',
  `create_time` bigint NOT NULL COMMENT '创建时间',
  `create_by_id` bigint NOT NULL COMMENT '创建人主键',
  `create_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人名称',
  `update_time` bigint NOT NULL COMMENT '更新时间',
  `update_by_id` bigint NOT NULL COMMENT '编辑人主键',
  `update_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人名称',
  `is_del` tinyint NOT NULL COMMENT '是否删除；0-否，1-是',
  `active_source_product_key` varchar(100) COLLATE utf8mb4_general_ci GENERATED ALWAYS AS ((case when ((`source_product_id` is not null) and (`is_del` = 0)) then concat(`vendor_id`,_utf8mb4':',`source_product_id`) else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_vendor_product_source` (`active_source_product_key`),
  KEY `idx_vendor_product_source_state` (`source_product_id`,`product_state`,`is_del`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商商品';
/*!40101 SET character_set_client = @saved_cs_client */;

