DROP TABLE IF EXISTS `vendor_product_audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor_product_audit_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `vendor_product_id` bigint DEFAULT NULL COMMENT '供应商商品 ID',
  `audit_state` tinyint DEFAULT NULL COMMENT '审核状态；0-待审核，1-审核通过，2-审核失败',
  `audit_fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核失败原因',
  `vendor_id` int NOT NULL COMMENT '供应商 ID',
  `create_time` bigint NOT NULL COMMENT '创建时间',
  `create_by_id` bigint NOT NULL COMMENT '创建人主键',
  `create_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人名称',
  `update_time` bigint NOT NULL COMMENT '更新时间',
  `update_by_id` bigint NOT NULL COMMENT '编辑人主键',
  `update_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人名称',
  `is_del` tinyint NOT NULL COMMENT '是否删除；0-否，1-是',
  PRIMARY KEY (`id`),
  KEY `vendor_product_audit_log_vendor_product_id_index` (`vendor_product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商商品审核记录';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `vendor_product_audit_log` DISABLE KEYS */;
