DROP TABLE IF EXISTS `vendor_product_gallery`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor_product_gallery` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `vendor_product_id` int NOT NULL COMMENT '供应商商品 ID',
  `pic_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品实际图片',
  `pic_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片说明信息 ',
  `pic_thumb` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '微缩图片url ',
  `pic_original` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原图url',
  `pic_large` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '高清图片url ',
  `sort_order` int NOT NULL COMMENT '排序',
  `vendor_id` int NOT NULL COMMENT '供应商 ID',
  `create_time` bigint NOT NULL COMMENT '创建时间',
  `create_by_id` bigint NOT NULL COMMENT '创建人主键',
  `create_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人名称',
  `update_time` bigint NOT NULL COMMENT '更新时间',
  `update_by_id` bigint NOT NULL COMMENT '编辑人主键',
  `update_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人名称',
  `is_del` tinyint NOT NULL COMMENT '是否删除；0-否，1-是',
  PRIMARY KEY (`id`),
  KEY `vendor_product_gallery_vendor_product_id_index` (`vendor_product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商商品相册';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `vendor_product_gallery` DISABLE KEYS */;
