DROP TABLE IF EXISTS `vendor_product_sku`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor_product_sku` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `vendor_product_id` int NOT NULL COMMENT '供应商商品 ID',
  `source_sku_id` int DEFAULT NULL COMMENT '来源店铺/门店SKU ID，无规格为0',
  `min_purchase_qty` int NOT NULL DEFAULT '1' COMMENT '最低采购数量',
  `sku_attr_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品规格值（拼接）',
  `sku_attr_json` json DEFAULT NULL COMMENT '商品规格值（json）',
  `sku_sn` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '规格编码',
  `sku_tsn` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '规格条形码',
  `sku_weight` decimal(10,2) DEFAULT NULL COMMENT '规格重量',
  `sku_stock` int DEFAULT NULL COMMENT '规格库存',
  `supply_price` decimal(10,2) NOT NULL COMMENT '供货价',
  `supply_price_limit_type` tinyint NOT NULL COMMENT '限售金额类型；1-按金额，2-按比例',
  `supply_price_limit_val` decimal(10,2) NOT NULL COMMENT '限售金额值',
  `sales_volume` int NOT NULL COMMENT '规格销量',
  `vendor_id` int NOT NULL COMMENT '供应商 ID',
  `create_time` bigint NOT NULL COMMENT '创建时间',
  `create_by_id` bigint NOT NULL COMMENT '创建人主键',
  `create_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人名称',
  `update_time` bigint NOT NULL COMMENT '更新时间',
  `update_by_id` bigint NOT NULL COMMENT '编辑人主键',
  `update_by_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人名称',
  `is_del` tinyint NOT NULL COMMENT '是否删除；0-否，1-是',
  `active_source_sku_key` varchar(100) COLLATE utf8mb4_general_ci GENERATED ALWAYS AS ((case when ((`source_sku_id` is not null) and (`is_del` = 0)) then concat(`vendor_product_id`,_utf8mb4':',`source_sku_id`) else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_vendor_product_source_sku` (`active_source_sku_key`),
  KEY `vendor_product_sku_vendor_product_id_index` (`vendor_product_id`),
  KEY `idx_vendor_product_source_sku` (`source_sku_id`,`is_del`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供货商商品规格';
/*!40101 SET character_set_client = @saved_cs_client */;

