DROP TABLE IF EXISTS `wechat_keyword_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wechat_keyword_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称，≤60，全局唯一（不区分大小写，依赖 utf8mb4_general_ci + uk_rule_name）',
  `reply_mode` tinyint NOT NULL DEFAULT '1' COMMENT '回复模式：1=随机回复一条 2=回复全部',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '启用状态：0=停用 1=启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_name` (`rule_name`),
  KEY `idx_enabled` (`enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='公众号关键字回复-规则主表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `wechat_keyword_rule` DISABLE KEYS */;
/*!40000 ALTER TABLE `wechat_keyword_rule` ENABLE KEYS */;
DROP TABLE IF EXISTS `wechat_keyword_rule_keyword`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wechat_keyword_rule_keyword` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_id` bigint NOT NULL COMMENT '所属规则 id（逻辑外键 wechat_keyword_rule.id）',
  `keyword` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关键字，≤30',
  `match_type` tinyint NOT NULL DEFAULT '1' COMMENT '匹配方式：1=全匹配 2=半匹配',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '规则内排序，0 起递增',
  PRIMARY KEY (`id`),
  KEY `idx_rule` (`rule_id`),
  KEY `idx_keyword_match` (`keyword`,`match_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='公众号关键字回复-关键字子表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `wechat_keyword_rule_keyword` DISABLE KEYS */;
/*!40000 ALTER TABLE `wechat_keyword_rule_keyword` ENABLE KEYS */;
DROP TABLE IF EXISTS `wechat_keyword_rule_reply`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wechat_keyword_rule_reply` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_id` bigint NOT NULL COMMENT '所属规则 id（逻辑外键 wechat_keyword_rule.id）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '规则内排序，0 起递增',
  `msg_type` tinyint NOT NULL DEFAULT '1' COMMENT '消息类型：1=文本 2=图文',
  `content_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '文本内容（msg_type=1 必填，≤300 字符）',
  `news_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图文标题（msg_type=2）',
  `news_cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图文封面图 URL（msg_type=2，HTTPS 公网可访问）',
  `news_description` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图文摘要（msg_type=2，≤120 字符）',
  `news_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图文跳转链接（msg_type=2 必填）',
  PRIMARY KEY (`id`),
  KEY `idx_rule` (`rule_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='公众号关键字回复-回复内容子表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `wechat_keyword_rule_reply` DISABLE KEYS */;
/*!40000 ALTER TABLE `wechat_keyword_rule_reply` ENABLE KEYS */;
DROP TABLE IF EXISTS `wechat_live`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wechat_live` (
  `wechat_live_id` int NOT NULL AUTO_INCREMENT,
  `wechat_live_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '直播标题',
  `wechat_live_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '直播内容',
  `act_range` tinyint NOT NULL DEFAULT '0' COMMENT '活动范围',
  `act_range_ext` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动简介',
  `room_id` int unsigned NOT NULL DEFAULT '0' COMMENT '房间号',
  `share_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分享图',
  `live_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '直播类型：0-手机直播，1-推流',
  `close_like` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否关闭点赞：0-开启，1-关闭',
  `close_goods` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否关闭货架：0-开启，1-关闭',
  `close_comment` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否关闭评论：0-开启，1-关闭',
  `close_kf` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否关闭客服：0-开启，1-关闭',
  `close_replay` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否关闭回放：0-开启，1-关闭',
  `is_feeds_public` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否开启官方收录：0-关闭，1-开启',
  `feeds_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '官方收录封面',
  `cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面图',
  `anchor_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主播ID',
  `anchor_openid` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主播微信openid',
  `anchor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主持人姓名',
  `anchor_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主持人图片',
  `creator_openid` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者openid',
  `live_status` int unsigned NOT NULL DEFAULT '0' COMMENT '直播状态',
  `start_time` int unsigned NOT NULL DEFAULT '0' COMMENT '开始时间',
  `end_time` int unsigned NOT NULL DEFAULT '0' COMMENT '结束时间',
  `last_update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '最后一次更新时间',
  `product_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品数据',
  `thumb_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '缩略图',
  `live_sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '直播编码',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺id',
  `sub_anchor_wechat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '副主播微信账号',
  `audit_status` int NOT NULL DEFAULT '0' COMMENT '审核状态：0-未审核，1-审核中，2-审核通过，3-审核驳回',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`wechat_live_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='小程序直播';
