/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wechat_live_goods` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `room_id` int DEFAULT NULL COMMENT '历史字段：直播间ID',
  `wechat_goods_id` int DEFAULT NULL COMMENT '微信商品ID',
  `product_id` bigint DEFAULT NULL COMMENT '系统商品ID',
  `product_sku_id` bigint NOT NULL DEFAULT '0' COMMENT '系统SKU ID，0表示无规格',
  `goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品名称',
  `cover_img` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品封面图',
  `price` bigint DEFAULT NULL COMMENT '商品价格（分）',
  `price_type` int DEFAULT NULL COMMENT '价格类型：1-一口价，2-价格区间，3-显示折扣价',
  `url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品小程序路径',
  `audit_status` int DEFAULT NULL COMMENT '商品状态：0-未审核，1-审核中，2-审核通过，3-审核驳回',
  `sort` int DEFAULT '0' COMMENT '历史字段：直播间商品排序',
  `is_show` int DEFAULT '0' COMMENT '历史字段：是否显示：0-显示，1-隐藏',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `shop_id` int DEFAULT NULL COMMENT '店铺ID',
  PRIMARY KEY (`id`),
  KEY `idx_shop_id` (`shop_id`),
  KEY `idx_wechat_goods_id` (`wechat_goods_id`),
  KEY `idx_product_sku_shop` (`product_id`,`product_sku_id`,`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='微信直播商品主表';
