/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wechat_live_sync_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_id` int DEFAULT NULL COMMENT '订单ID',
  `aftersale_id` int DEFAULT NULL COMMENT '售后ID',
  `refund_id` int DEFAULT NULL COMMENT '退款ID',
  `room_id` int DEFAULT NULL COMMENT '直播房间ID',
  `event_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件类型',
  `direction` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '同步方向：OUTBOUND/INBOUND',
  `sync_status` tinyint DEFAULT '0' COMMENT '同步状态：0待同步，1成功，2失败，3跳过，4部分同步',
  `idempotent_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '幂等键',
  `request_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '请求数据',
  `response_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '响应数据',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误信息',
  `retry_count` int DEFAULT '0' COMMENT '重试次数',
  `last_sync_time` bigint DEFAULT NULL COMMENT '最近同步时间',
  `next_retry_time` bigint DEFAULT NULL COMMENT '下次重试时间',
  `shop_id` int DEFAULT NULL COMMENT '店铺ID',
  `add_time` bigint DEFAULT NULL COMMENT '创建时间',
  `update_time` bigint DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_order_event` (`order_id`,`event_type`),
  KEY `idx_status_direction` (`sync_status`,`direction`),
  KEY `idx_room_id` (`room_id`),
  KEY `idx_idempotent_key` (`idempotent_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='微信直播同步日志表';
